--
-- Set default database
--
--
-- Create table `users`
--
CREATE TABLE users (
  id varchar(13) NOT NULL,
  nombre1 varchar(60) NOT NULL,
  nombre2 varchar(60) DEFAULT NULL,
  apellido1 varchar(60) NOT NULL,
  apellido2 varchar(60) NOT NULL,
  tipo_documento tinyint(4) NOT NULL DEFAULT 1,
  id_pais tinyint(4) DEFAULT NULL,
  ciudad varchar(60) DEFAULT NULL,
  direccion varchar(255) DEFAULT NULL,
  email varchar(191) DEFAULT NULL,
  telefono1 varchar(60) DEFAULT NULL,
  telefono2 varchar(60) DEFAULT NULL,
  ocupacion varchar(60) DEFAULT NULL,
  estado tinyint(4) DEFAULT NULL,
  fecha_nacimiento date DEFAULT NULL,
  password varchar(191) NOT NULL,
  imagen_url varchar(100) NOT NULL,
  id_tipo_usuario tinyint(4) NOT NULL,
  max_procedimiento tinyint(4) DEFAULT 5,
  max_consulta tinyint(4) DEFAULT 5,
  color varchar(40) DEFAULT NULL,
  registro_doctor varchar(60) DEFAULT NULL,
  uso_sistema tinyint(4) DEFAULT 0,
  training tinyint(4) DEFAULT 0,
  remember_token varchar(100) DEFAULT NULL,
  id_usuariocrea varchar(13) NOT NULL,
  id_usuariomod varchar(13) NOT NULL,
  ip_creacion varchar(40) NOT NULL,
  ip_modificacion varchar(40) NOT NULL,
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  deleted_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  uso_laboratorio tinyint(4) DEFAULT 1,
  departamento varchar(50) DEFAULT NULL,
  cargo varchar(50) DEFAULT NULL,
  servicios varchar(50) DEFAULT NULL,
  libro varchar(50) DEFAULT NULL,
  folio varchar(50) DEFAULT NULL,
  numero varchar(50) DEFAULT NULL,
  app tinyint(4) NOT NULL DEFAULT 0,
  uso_pentax tinyint(4) DEFAULT 0 COMMENT '1: endoscopicos; 2: ambos; 3: funcionales',
  id_ciudad_usuario int(11) DEFAULT NULL,
  urbanizacion varchar(50) DEFAULT NULL,
  etapa varchar(50) DEFAULT NULL,
  manzana varchar(50) DEFAULT NULL,
  villa varchar(50) DEFAULT NULL,
  referencia_direccion text DEFAULT NULL,
  area varchar(255) DEFAULT NULL,
  new_system tinyint(4) DEFAULT 0,
  excluidos tinyint(4) DEFAULT 0,
  nombres varchar(60) NOT NULL,
  apellidos varchar(60) NOT NULL,
  pais int(11) NOT NULL,
  institucion varchar(100) NOT NULL,
  tipoUsuario int(11) NOT NULL,
  cedula varchar(13) DEFAULT NULL,
  telefono3 varchar(15) DEFAULT NULL,
  fechanacimiento date DEFAULT NULL,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 3276,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

