  tipo_documento varchar(2) DEFAULT NULL,
  rise int(11) DEFAULT 0,
  contabilidad int(11) DEFAULT 0,
  contribuyente_especial varchar(13) DEFAULT '',
  estado tinyint(1) NOT NULL DEFAULT 1,
  pais varchar(75) DEFAULT NULL,
  provincia varchar(75) DEFAULT NULL,
  urbanizacion varchar(150) DEFAULT NULL,
  etapa varchar(50) DEFAULT NULL,
  manzana varchar(50) DEFAULT NULL,
  villa_solar varchar(50) DEFAULT NULL,
  referencia varchar(255) DEFAULT NULL,
  web varchar(255) DEFAULT NULL,
  id_ciudad int(11) DEFAULT NULL,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
CHARACTER SET utf8mb3,
