  nombre2familiar varchar(255) DEFAULT NULL,
  apellido1familiar varchar(255) DEFAULT NULL,
  apellido2familiar varchar(255) DEFAULT NULL,
  parentesco varchar(255) DEFAULT NULL,
  parentescofamiliar varchar(255) DEFAULT NULL,
  referido varchar(255) DEFAULT NULL,
  vacuna mediumtext DEFAULT NULL,
  telefono3 varchar(60) DEFAULT NULL,
  ocupacion varchar(60) DEFAULT NULL,
  lugar_nacimiento varchar(255) DEFAULT NULL,
  id_usuariocrea varchar(13) DEFAULT NULL,
