  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  deleted_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  antecedentes_pat mediumtext DEFAULT NULL,
  antecedentes_fam mediumtext DEFAULT NULL,
  antecedentes_quir mediumtext DEFAULT NULL,
  transfusion varchar(2) DEFAULT NULL,
  alcohol varchar(250) DEFAULT NULL,
  primera_mens tinyint(4) DEFAULT NULL,
  menopausia tinyint(4) DEFAULT NULL,
  anticonceptivos varchar(255) DEFAULT NULL,
  hijos_vivos tinyint(4) DEFAULT 0,
  hijos_muertos tinyint(4) DEFAULT 0,
  parto_normal tinyint(4) DEFAULT 0,
  parto_cesarea tinyint(4) DEFAULT 0,
  aborto tinyint(4) DEFAULT 0,
  id_subseguro tinyint(4) DEFAULT NULL,
  codigo varchar(60) DEFAULT NULL,
  fecha_codigo date DEFAULT NULL,
  altura float DEFAULT 0,
  peso float DEFAULT 0,
  temperatura float DEFAULT 0,
  presion float DEFAULT 0,
  historia_clinica longtext DEFAULT NULL,
  observacion longtext DEFAULT NULL,
  trabajo varchar(100) DEFAULT NULL,
  telefono_llamar varchar(15) DEFAULT NULL,
  religion varchar(60) DEFAULT NULL,
  mail_primera_vez tinyint(4) DEFAULT 0,
  origen varchar(255) DEFAULT NULL,
  origen2 varchar(255) DEFAULT NULL,
  otro varchar(255) DEFAULT NULL,
