  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  dieta tinyint(4) DEFAULT 0 COMMENT '0: no es dieta, 1: es dieta',
  iess tinyint(4) NOT NULL DEFAULT 0 COMMENT '1.- IESS; 2.- IESS NOTA ENTREGA',
  laboratorio varchar(255) DEFAULT NULL,
  precio_unitario float DEFAULT NULL,
  precio_total float DEFAULT NULL,
  atc varchar(255) DEFAULT NULL,
  indicaciones text DEFAULT NULL,
  contraindicaciones text DEFAULT NULL,
  dosis_pediatrica text DEFAULT NULL,
  consep varchar(255) DEFAULT NULL,
