--
-- Create table `producto`
--
CREATE TABLE producto (
  id int(11) NOT NULL AUTO_INCREMENT,
  nombre varchar(250) NOT NULL,
  descripcion varchar(250) NOT NULL,
  estado tinyint(4) NOT NULL DEFAULT 1,
  medida varchar(5) NOT NULL,
  minimo float NOT NULL,
  precio_compra float DEFAULT NULL,
  precio_venta float DEFAULT NULL,
  codigo varchar(50) NOT NULL,
  codigo_iess varchar(50) DEFAULT NULL,
  despacho int(4) NOT NULL COMMENT '1: codigo de serie,0: por unidad',
  cantidad float DEFAULT 0,
  tipo_producto int(11) DEFAULT 0 COMMENT '0: no usado, 1:usado en procedimiento',
  cantidad_unidad int(11) DEFAULT NULL,
  id_marca int(11) DEFAULT NULL,
  registro_sanitario varchar(255) NOT NULL,
  usos int(10) NOT NULL DEFAULT 1,
  codigo_siempre tinyint(4) DEFAULT 0,
  id_usuariocrea varchar(13) NOT NULL,
  id_usuariomod varchar(13) NOT NULL,
  ip_creacion varchar(40) NOT NULL,
  ip_modificacion varchar(40) NOT NULL,
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP() ON UPDATE CURRENT_TIMESTAMP,
  iva tinyint(4) DEFAULT 1 COMMENT '0: no posee iva, 1:possee iva',
  descuento tinyint(4) DEFAULT 0,
  tipo int(11) NOT NULL DEFAULT 0,
  imagen_producto varchar(255) DEFAULT NULL,
  kardex_uso tinyint(4) DEFAULT NULL,
  cantidad_usos_kardex int(11) DEFAULT NULL,
  gtin varchar(255) DEFAULT NULL,
  unidades int(11) DEFAULT NULL,
  farmacia tinyint(4) DEFAULT 0 COMMENT '1: FARMACIA SI - 0: NO',
  ficha_tecnica text DEFAULT NULL,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 1489,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
COMMENT = 'FK_producto_tipo_producto',
