  id_banco int(11) DEFAULT NULL,
  numero_cuenta varchar(25) DEFAULT NULL,
  url_apps varchar(45) DEFAULT NULL,
  apps tinyint(4) DEFAULT 0,
  parroquia varchar(25) DEFAULT NULL,
  canton varchar(25) DEFAULT NULL,
  provincia varchar(25) DEFAULT NULL,
  resolucion varchar(30) DEFAULT NULL,
  egreso_kardex tinyint(4) DEFAULT 0,
  abreviatura varchar(10) DEFAULT NULL,
  logo_receta varchar(255) DEFAULT NULL,
  abreviatura_emp varchar(10) DEFAULT NULL,
  imagen_producto tinyint(4) DEFAULT 0,
  factura_seguro tinyint(4) DEFAULT 0,
  contraentrega tinyint(4) DEFAULT 0,
