  urbanizacion varchar(255) DEFAULT NULL,
  etapa varchar(255) DEFAULT NULL,
  manzana varchar(255) DEFAULT NULL,
  villa varchar(255) DEFAULT NULL,
  referencia text DEFAULT NULL,
  id_bd int(11) DEFAULT NULL,
  compras tinyint(4) NOT NULL DEFAULT 0,
  union_producto tinyint(4) DEFAULT 0 COMMENT '0= Creacion individual   1= se crea en ambos lados',
  leyenda text DEFAULT NULL,
  url_datafast varchar(70) DEFAULT NULL,
  id_entidad varchar(50) DEFAULT NULL,
  access_token varchar(75) DEFAULT NULL,
  shopper_mid varchar(20) DEFAULT NULL,
  shopper_tid varchar(20) DEFAULT NULL,
  test_mode tinyint(4) DEFAULT 0 COMMENT '0 prod 1 prueba',
  risk varchar(25) DEFAULT NULL,
  clave_firma_ofi varchar(255) DEFAULT NULL,
  clave_firma_sop varchar(255) DEFAULT NULL,
  PRIMARY KEY (id)
