  anio int(5) NOT NULL,
  mes tinyint(4) NOT NULL,
  estado tinyint(4) NOT NULL DEFAULT 1,
  estado_pago tinyint(4) NOT NULL DEFAULT 0,
  id_doctor_ieced varchar(13) DEFAULT NULL,
  doctor_txt varchar(255) DEFAULT NULL,
  id_seguro int(11) DEFAULT NULL,
  id_protocolo int(11) DEFAULT NULL,
  id_nivel int(11) DEFAULT NULL,
  est_amb_hos tinyint(4) DEFAULT NULL,
  cantidad int(11) NOT NULL,
  valor decimal(18, 4) NOT NULL DEFAULT 0.0000,
  id_empresa varchar(13) DEFAULT NULL,
  hcid int(11) DEFAULT NULL,
  id_agenda int(11) DEFAULT NULL,
  realizado tinyint(4) DEFAULT 0,
  observacion varchar(255) DEFAULT NULL,
  fecha_convenios datetime DEFAULT NULL,
  id_forma_de_pago int(11) UNSIGNED DEFAULT NULL,
  motivo_descuento varchar(255) DEFAULT NULL,
  descuento_p float NOT NULL DEFAULT 0,
  descuento_valor decimal(18, 4) NOT NULL DEFAULT 0.0000,
  recargo_p float NOT NULL DEFAULT 0,
  recargo_valor decimal(18, 4) NOT NULL DEFAULT 0.0000,
  total_valor decimal(18, 4) NOT NULL DEFAULT 0.0000,
  tarjeta varchar(255) DEFAULT NULL,
  fecha_orden timestamp NULL DEFAULT NULL,
  er_biometria tinyint(4) DEFAULT 0,
  er_bioquimica tinyint(4) DEFAULT 0,
  er_manual tinyint(4) DEFAULT 0,
  doctor_firma varchar(13) DEFAULT NULL,
  id_usuariocrea varchar(13) NOT NULL,
  id_usuariomod varchar(13) NOT NULL,
  ip_creacion varchar(40) NOT NULL,
  ip_modificacion varchar(40) NOT NULL,
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP() ON UPDATE CURRENT_TIMESTAMP,
  completo tinyint(4) DEFAULT 0,
  numorden_iess varchar(255) DEFAULT NULL,
  historia_iess varchar(255) DEFAULT NULL,
  estado_orden_iess tinyint(4) DEFAULT 0,
  codigo varchar(10) DEFAULT NULL,
  enviado_doctor_externo tinyint(4) NOT NULL DEFAULT 0 COMMENT '1: enviado; 0: no enviado',
  pres_dom tinyint(4) DEFAULT 0,
  pago_online tinyint(4) DEFAULT 0,
  fecha_tentativa datetime DEFAULT NULL,
  tipo_documento tinyint(4) DEFAULT NULL COMMENT ' 4. ruc 5. cedula 6. pasaporte 8. extranjero',
  cedula_factura varchar(13) DEFAULT NULL,
  nombre_factura varchar(255) DEFAULT NULL,
  apellido_factura varchar(255) DEFAULT NULL,
  direccion_factura varchar(255) DEFAULT NULL,
  ciudad_factura varchar(255) DEFAULT NULL,
  email_factura varchar(255) DEFAULT NULL,
  telefono_factura varchar(60) DEFAULT NULL,
  ticket varchar(10) DEFAULT NULL,
  gestion tinyint(4) DEFAULT 0,
  proceso tinyint(4) DEFAULT 0,
  total_nivel2 decimal(10, 4) DEFAULT NULL,
  toma_muestra datetime DEFAULT NULL,
  comprobante varchar(255) DEFAULT NULL,
  fecha_envio datetime DEFAULT NULL,
  orden_agrupado int(11) DEFAULT NULL,
  venta_gastro int(11) DEFAULT NULL,
  numero_oda varchar(255) DEFAULT NULL,
  cobrar_pac_pct decimal(10, 2) DEFAULT 100.00,
  valor_con_oda decimal(10, 4) DEFAULT 0.0000,
  total_con_oda decimal(10, 4) DEFAULT 0.0000,
  estado_venta tinyint(4) NOT NULL DEFAULT 0,
  estado_comision tinyint(4) NOT NULL DEFAULT 0,
  membresia_id int(11) DEFAULT NULL,
  membresia_detalle_id int(11) DEFAULT NULL,
  resultados_estado tinyint(4) DEFAULT 0,
  asesor_venta varchar(13) DEFAULT NULL,
  puntos_aplicados int(11) DEFAULT NULL,
  sucursal varchar(3) DEFAULT NULL,
  punto_emision varchar(3) DEFAULT NULL,
  pct_resultado decimal(10, 4) DEFAULT NULL,
  observacion_app text DEFAULT NULL,
  estado_comision2 tinyint(4) DEFAULT 0 COMMENT 'determina si ya se cargo los valores de la comision en el detalle de la orden',
  total_comision decimal(10, 4) DEFAULT 0.0000,
  comentario varchar(255) DEFAULT NULL,
  leido_bd tinyint(4) NOT NULL DEFAULT 0,
  otros varchar(255) DEFAULT NULL,
  prioridad_orden tinyint(4) NOT NULL DEFAULT 0,
  proceso_aut tinyint(4) DEFAULT 0,
  observacion_adicional varchar(255) DEFAULT NULL,
  total_planilla decimal(18, 2) DEFAULT NULL,
  deducible decimal(18, 2) DEFAULT NULL,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 423,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

