--
-- Create table `ct_productos`
--
CREATE TABLE ct_productos (
  id int(11) NOT NULL AUTO_INCREMENT,
  codigo varchar(255) NOT NULL,
  nombre varchar(255) NOT NULL,
  codigo_barra varchar(255) DEFAULT NULL,
  tipo tinyint(4) DEFAULT NULL,
  descripcion varchar(255) DEFAULT NULL,
  clase varchar(25) DEFAULT NULL,
  grupo varchar(13) DEFAULT NULL COMMENT '1= Insumos, 2=Medicamentos, 3=Servicios, 4=Procedimientos, 5=Otros, 6=Honorario Medico, 7 =Equipo, 8=Honorario Anestesiologo, 9=Membresias',
  proveedor varchar(13) DEFAULT NULL,
  cta_gastos varchar(255) DEFAULT NULL,
  cta_ventas varchar(255) DEFAULT NULL,
  cta_costos varchar(255) DEFAULT NULL,
  cta_devolucion varchar(255) DEFAULT NULL,
  reg_serie tinyint(4) DEFAULT 0,
  mod_precio tinyint(4) DEFAULT 0,
  mod_desc tinyint(4) DEFAULT 0,
  marca varchar(50) DEFAULT NULL,
  modelo varchar(25) DEFAULT NULL,
  stock_minimo tinyint(4) DEFAULT NULL,
  fecha_expiracion date DEFAULT NULL,
  impuesto_iva_compras varchar(13) DEFAULT NULL,
  impuesto_iva_ventas varchar(13) DEFAULT NULL,
  impuesto_servicio varchar(50) DEFAULT NULL,
  impuesto_ice varchar(50) DEFAULT NULL,
  clasificacion_impuesto_ice varchar(50) DEFAULT NULL,
  promedio double DEFAULT NULL,
  reposicion double DEFAULT NULL,
  lista double DEFAULT NULL,
  ultima_compra double DEFAULT NULL,
  precio1 double DEFAULT NULL,
  precio2 double DEFAULT NULL,
  precio3 double DEFAULT NULL,
  precio4 double DEFAULT NULL,
  promocion double DEFAULT NULL,
  descuento double DEFAULT NULL,
  financiero double DEFAULT NULL,
  ident_paquete tinyint(4) DEFAULT 0,
  valor_total_paq decimal(18, 2) DEFAULT NULL,
  estado_tabla tinyint(4) DEFAULT 1,
  id_usuariocrea varchar(13) DEFAULT NULL,
  id_usuariomod varchar(13) DEFAULT NULL,
  ip_creacion varchar(40) DEFAULT NULL,
  ip_modificacion varchar(40) DEFAULT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  iva tinyint(4) DEFAULT 0,
  observacion_divisa text DEFAULT NULL,
  id_empresa varchar(17) DEFAULT NULL,
  gtin varchar(255) DEFAULT NULL,
  unidades int(11) DEFAULT NULL,
  tipo_objeto varchar(1) DEFAULT 'P',
  tipo_producto tinyint(4) NOT NULL DEFAULT 1,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 375,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

