--
-- Create table `ct_nota_credito_clientes`
--
CREATE TABLE ct_nota_credito_clientes (
  id int(11) NOT NULL AUTO_INCREMENT,
  id_empresa varchar(13) NOT NULL,
  id_cliente varchar(25) NOT NULL,
  check_sri tinyint(4) DEFAULT NULL,
  id_asiento_cabecera int(11) NOT NULL,
  sucursal varchar(3) DEFAULT NULL,
  punto_emision varchar(3) DEFAULT NULL,
  numero_factura varchar(255) DEFAULT NULL,
  secuencia varchar(255) DEFAULT NULL,
  nro_comprobante varchar(60) DEFAULT NULL,
  nro_autorizacion varchar(255) DEFAULT NULL,
  fecha date NOT NULL,
  tipo varchar(10) NOT NULL,
  concepto varchar(255) DEFAULT NULL,
  descuento decimal(18, 2) DEFAULT NULL,
  subtotal decimal(18, 2) DEFAULT NULL,
  impuesto decimal(18, 2) DEFAULT NULL,
  sub_sin_imp decimal(18, 2) DEFAULT NULL,
  tar_iva_12 decimal(18, 2) DEFAULT NULL,
  total_credito decimal(18, 2) NOT NULL,
  total_deudas decimal(18, 2) DEFAULT NULL,
  total_abonos decimal(18, 2) DEFAULT NULL,
  total_nuevo_saldo decimal(18, 2) DEFAULT NULL,
  observacion varchar(255) DEFAULT NULL,
  estado tinyint(4) NOT NULL DEFAULT 1,
  id_usuariocrea varchar(13) NOT NULL,
  id_usuariomod varchar(13) NOT NULL,
  ip_creacion varchar(40) NOT NULL,
  ip_modificacion varchar(40) NOT NULL,
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  fecha_envio date DEFAULT NULL,
  estado_electronica tinyint(4) DEFAULT 0 COMMENT '0: enviado, 1: firmado, 2: recibido, 3:autorizado',
  electronica tinyint(4) DEFAULT 0,
  subtotal0 decimal(18, 2) DEFAULT 0.00,
  subtotal12 decimal(18, 2) DEFAULT 0.00,
  tipo_nota tinyint(4) DEFAULT 1 COMMENT '1) CREDITO NORMAL 2) PARCIAL',
  id_factura int(11) DEFAULT NULL,
  doc_electronico tinyint(4) DEFAULT NULL,
  clave_acceso varchar(100) DEFAULT NULL,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 4096,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

