--
-- Create table `ct_compras`
--
CREATE TABLE ct_compras (
  id int(11) NOT NULL AUTO_INCREMENT,
  numero varchar(25) DEFAULT NULL,
  secuencia_f varchar(255) DEFAULT '',
  punto_emision varchar(255) NOT NULL,
  sucursal varchar(255) NOT NULL,
  id_asiento_cabecera int(11) NOT NULL,
  tipo tinyint(4) NOT NULL DEFAULT 1 COMMENT '2: Factura Contable 3: Saldos Iniciales',
  fecha_termino date DEFAULT NULL,
  fecha date NOT NULL,
  estado tinyint(4) NOT NULL DEFAULT 1 COMMENT 'estado 2: con retencion',
  archivo_sri tinyint(4) DEFAULT NULL,
  proveedor varchar(13) NOT NULL,
  direccion_proveedor varchar(255) DEFAULT NULL,
  termino int(11) DEFAULT NULL,
  orden_compra varchar(25) DEFAULT NULL,
  f_caducidad date NOT NULL,
  tipo_gasto varchar(25) DEFAULT NULL,
  autorizacion varchar(225) DEFAULT NULL,
  f_autorizacion date DEFAULT NULL,
  serie varchar(50) NOT NULL DEFAULT '0',
  secuencia_factura varchar(50) DEFAULT '0',
  credito_tributario varchar(50) DEFAULT NULL,
  tipo_comprobante varchar(50) NOT NULL,
  observacion varchar(255) DEFAULT NULL,
  subtotal decimal(18, 4) DEFAULT 0.0000,
  descuento decimal(18, 4) DEFAULT 0.0000,
  subtotal_0 decimal(18, 4) DEFAULT 0.0000,
  subtotal_12 decimal(18, 4) DEFAULT 0.0000,
  iva_total decimal(18, 4) DEFAULT 0.0000,
  ice_total decimal(18, 4) DEFAULT 0.0000,
  transporte decimal(18, 4) DEFAULT 0.0000,
  valor_contable decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT 'Valor para reportes',
  total_final decimal(18, 4) DEFAULT NULL,
  id_empresa varchar(13) NOT NULL,
  id_usuariocrea varchar(13) NOT NULL,
  id_usuariomod varchar(13) NOT NULL,
  ip_creacion varchar(40) NOT NULL,
  ip_modificacion varchar(40) NOT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  pedido varchar(45) DEFAULT NULL,
  rutapdf varchar(255) DEFAULT NULL,
  doc_electronico tinyint(4) DEFAULT 0,
  electronica tinyint(4) DEFAULT 0,
  nro_comprobante varchar(100) DEFAULT NULL,
  nro_autorizacion varchar(100) DEFAULT NULL,
  forma_pago varchar(2) DEFAULT '01',
  emisor varchar(255) DEFAULT NULL,
  clave_acceso varchar(100) DEFAULT NULL,
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 1,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

