DELIMITER $$

--
-- Create procedure `sp_p_new_balance`
--
CREATE
PROCEDURE sp_p_new_balance (IN fecha_desde varchar(255), IN fecha_hasta varchar(255))
BEGIN
  SELECT
    *
  FROM (SELECT
      pl.plan,
      pl.nombre,
      SUM(debe) AS debe,
      SUM(haber) AS haber,
      IF(SUM(debe) > SUM(haber), SUM(debe) - SUM(haber), 0) AS deudor,
      IF(SUM(debe) < SUM(haber), SUM(haber) - SUM(debe), 0) AS acreedor
    FROM ct_asientos_detalle d
      INNER JOIN ct_asientos_cabecera c
        ON d.id_asiento_cabecera = c.id
      INNER JOIN plan_cuentas_empresa pl
        ON d.id_plan_cuenta = pl.id_plan
        AND pl.id_empresa = c.id_empresa
    WHERE c.fecha_asiento > '2010-01-01'
    AND c.fecha_asiento <= '2024-09-30 23:59:59'
    AND c.id_empresa = '1793135579001'
    AND (pl.plan LIKE '1%'
    OR pl.plan LIKE '2%'
    OR pl.plan LIKE '3%')
    GROUP BY pl.plan

    UNION ALL
    SELECT
      pl.plan,
      pl.nombre,
      SUM(debe) AS debe,
      SUM(haber) AS haber,
      IF(SUM(debe) > SUM(haber), SUM(debe) - SUM(haber), 0) AS deudor,
      IF(SUM(debe) < SUM(haber), SUM(haber) - SUM(debe), 0) AS acreedor
    FROM ct_asientos_detalle d
      INNER JOIN ct_asientos_cabecera c
        ON d.id_asiento_cabecera = c.id
      INNER JOIN plan_cuentas_empresa pl
        ON d.id_plan_cuenta = pl.id_plan
        AND pl.id_empresa = c.id_empresa
    WHERE c.fecha_asiento BETWEEN fecha_desde AND fecha_hasta
    AND c.id_empresa = '1793135579001'
    AND (pl.plan LIKE '4%'
    OR pl.plan LIKE '5%')
    GROUP BY pl.plan) AS libro_diario
  ORDER BY libro_diario.plan;
END
$$

--
-- Create procedure `sp_proveedores_deudas_pagos_copy`
--
CREATE
PROCEDURE sp_proveedores_deudas_pagos_copy (IN id_empresa varchar(255), IN desde varchar(255), IN hasta varchar(255), IN id_proveedor varchar(255))
BEGIN
  SET @saldo := 0;
  IF id_proveedor = '' THEN

    SELECT
      *,
      IF(dvp.tipo = 'Factura', dvp.valor, 0) AS compra,
      IF(dvp.tipo != 'Factura', dvp.valor, 0) AS abono,
      @saldo := @saldo + IF(dvp.tipo = 'Factura', dvp.valor, -dvp.valor) AS saldo_acumulado
    FROM (SELECT
        *
      FROM ((SELECT
            0 AS orden,
            cc.id AS id_compra_,
            cc.id AS id_compra,
            'Factura' AS tipo,
            CONCAT(p.razonsocial, ' Fact: # ', cc.numero, ' Ref: ', cc.id, ' -- Asiento ', cc.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cc.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
            CONCAT('COM-FA ', cc.secuencia_f) AS Comprobante,
            cc.total_final AS valor,
            cc.id_asiento_cabecera AS id_asiento
          FROM ct_compras cc
            JOIN proveedor p
              ON cc.proveedor = p.id
            LEFT JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cc.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          GROUP BY cc.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            1 AS orden,
            cc.id AS id_compra_,
            cdce.id_compra,
            'CE' AS tipo,
            CONCAT(p.razonsocial, ' # ', cdce.observacion, ' Ref: ', cdce.id_secuencia, ' -- Asiento ', cce.id_asiento_cabecera, ' #Egreso: ', cdce.id_comprobante, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cce.fecha_comprobante,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-EG ', cce.secuencia),
            cc.total_final AS valor,
            cce.id_asiento_cabecera
          FROM ct_detalle_comprobante_egreso cdce
            JOIN ct_compras cc
              ON cdce.id_compra = cc.id
            JOIN ct_comprobante_egreso cce
              ON cce.id = cdce.id_comprobante
            JOIN ct_caja_banco ccb
              ON ccb.id = cce.id_caja_banco
            JOIN proveedor p
              ON p.id = cce.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cce.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND cce.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          GROUP BY cdce.id_compra
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            2 AS orden,
            cc.id AS id_compra_,
            cdbd.id_compra,
            'DebBnc' AS tipo,
            CONCAT(p.razonsocial, ' # ', cdb.concepto, ' Ref: ', cdbd.numero, ' -- Asiento ', cdb.id_asiento, ' #Debito: ', cdb.id, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cdb.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('BAN-ND ', cdb.secuencia),
            cdbd.abono AS valor,
            cdb.id_asiento
          FROM ct_debito_bancario_detalle cdbd
            JOIN ct_debito_bancario cdb
              ON cdb.id = cdbd.id_debito
            JOIN ct_compras cc
              ON cc.id = cdbd.id_compra
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cdb.id_asiento
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
            JOIN proveedor p
              ON p.id = cdb.id_acreedor
            JOIN ct_caja_banco ccb
              ON ccb.id = cdb.id_banco
          WHERE cc.estado <> '0'
          AND cdb.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          GROUP BY cdbd.id_compra
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            3 AS orden,
            cc.id AS id_compra_,
            cdcem.id,
            'EgMas' AS tipo,
            CONCAT(p.razonsocial, ' # ', ccem.descripcion, ' Ref: ', cdcem.id_secuencia, ' -- Asiento ', ccem.id_asiento_cabecera, ' #Egreso Masivo: ', cdcem.id, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            ccem.fecha_comprobante,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-M ', ccem.secuencia),
            cdcem.abono AS valor,
            ccem.id_asiento_cabecera
          FROM ct_comprobante_egreso_masivo ccem
            JOIN ct_detalle_comprobante_egreso_masivo cdcem
              ON cdcem.id_comprobante = ccem.id
            JOIN ct_compras cc
              ON cc.id = cdcem.id_compra
            JOIN proveedor p
              ON p.id = cdcem.id_proveedor
            JOIN ct_caja_banco ccb
              ON ccb.id = ccem.id_caja_banco
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = ccem.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND ccem.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          GROUP BY cdcem.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            4 AS orden,
            cc.id AS id_compra_,
            ccv.id,
            'CRUV' AS tipo,
            CONCAT(p.razonsocial, ' # ', ccv.detalle, ' Ref: ', cdc.secuencia_factura, ' #Cruce: ', cdc.id_comprobante, ' -- Asiento ', ccv.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cdc.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-CR-AF ', ccv.secuencia),
            cdc.total AS valor,
            ccv.id_asiento_cabecera
          FROM ct_cruce_valores ccv
            JOIN ct_detalle_cruce cdc
              ON cdc.id_comprobante = ccv.id
            JOIN ct_compras cc
              ON cc.id = cdc.id_factura
            JOIN proveedor p
              ON p.id = ccv.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = ccv.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND ccv.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          GROUP BY ccv.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            5 AS orden,
            cc.id AS id_compra_,
            cr.id,
            'Ret' AS tipo,
            CONCAT(p.razonsocial, ' # ', cr.descripcion, ' Ref: ', cc.secuencia_f, ' #Retencion: ', cr.id, ' -- Asiento ', cr.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cr.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-RE ', cr.secuencia),
            cr.total AS valor,
            cr.id_asiento_cabecera
          FROM ct_retenciones cr
            JOIN ct_compras cc
              ON cc.id = cr.id_compra
            JOIN proveedor p
              ON p.id = cr.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cr.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND cr.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          GROUP BY cr.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            6 AS orden,
            cc.id AS id_compra_,
            cda.id,
            'DbAcr' AS tipo,
            CONCAT(p.razonsocial, ' # ', cda.concepto, ' Ref: ', cc.secuencia_f, ' #Debito: ', cdda.id_debito_acreedores, ' -- Asiento ', cda.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cda.fechand,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-DB ', cc.secuencia_factura),
            cda.valor_contable AS valor,
            cda.id_asiento_cabecera
          FROM ct_debito_acreedores cda
            JOIN ct_detalle_debito_acreedores cdda
              ON cdda.id_debito_acreedores = cda.id
            JOIN ct_compras cc
              ON cc.id = cdda.id_factura
            JOIN proveedor p
              ON p.id = cda.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cda.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND cda.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          GROUP BY cda.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            7 AS orden,
            cc.id AS id_compra_,
            ccc.id,
            'CruCta' AS tipo,
            CONCAT(p.razonsocial, ' # ', ccc.detalle, ' Ref: ', cc.secuencia_f, ' #Cruce_Cuentas: ', ccc.id, ' -- Asiento ', ccc.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            ccc.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('CRUCE-CUENTAS ', ccc.secuencia),
            ccc.total AS valor,
            ccc.id_asiento_cabecera
          FROM ct_cruce_cuentas ccc
            JOIN ct_compras cc
              ON cc.id = ccc.id_factura
            JOIN proveedor p
              ON p.id = ccc.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = ccc.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND ccc.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          GROUP BY ccc.id
          ORDER BY cc.f_autorizacion DESC)) AS dvp
      ORDER BY dvp.fecha DESC, dvp.id_compra_) AS dvp
    ORDER BY dvp.fecha DESC, dvp.id_compra_;
  ELSE
    SELECT
      *,
      IF(dvp.tipo = 'Factura', dvp.valor, 0) AS compra,
      IF(dvp.tipo != 'Factura', dvp.valor, 0) AS abono,
      @saldo := @saldo + IF(dvp.tipo = 'Factura', dvp.valor, -dvp.valor) AS saldo_acumulado
    FROM (SELECT
        *
      FROM ((SELECT
            0 AS orden,
            cc.id AS id_compra_,
            cc.id AS id_compra,
            'Factura' AS tipo,
            CONCAT(p.razonsocial, ' Fact: # ', cc.numero, ' Ref: ', cc.id, ' -- Asiento ', cc.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cc.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
            CONCAT('COM-FA ', cc.secuencia_f) AS Comprobante,
            cc.total_final AS valor,
            cc.id_asiento_cabecera AS id_asiento
          FROM ct_compras cc
            JOIN proveedor p
              ON cc.proveedor = p.id
            LEFT JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cc.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          AND cc.proveedor = id_proveedor
          GROUP BY cc.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            1 AS orden,
            cc.id AS id_compra_,
            cdce.id_compra,
            'CE' AS tipo,
            CONCAT(p.razonsocial, ' # ', cdce.observacion, ' Ref: ', cdce.id_secuencia, ' -- Asiento ', cce.id_asiento_cabecera, ' #Egreso: ', cdce.id_comprobante, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cce.fecha_comprobante,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-EG ', cce.secuencia),
            cc.total_final AS valor,
            cce.id_asiento_cabecera
          FROM ct_detalle_comprobante_egreso cdce
            JOIN ct_compras cc
              ON cdce.id_compra = cc.id
            JOIN ct_comprobante_egreso cce
              ON cce.id = cdce.id_comprobante
            JOIN ct_caja_banco ccb
              ON ccb.id = cce.id_caja_banco
            JOIN proveedor p
              ON p.id = cce.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cce.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND cce.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          AND cc.proveedor = id_proveedor
          GROUP BY cdce.id_compra
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            2 AS orden,
            cc.id AS id_compra_,
            cdbd.id_compra,
            'DebBnc' AS tipo,
            CONCAT(p.razonsocial, ' # ', cdb.concepto, ' Ref: ', cdbd.numero, ' -- Asiento ', cdb.id_asiento, ' #Debito: ', cdb.id, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cdb.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('BAN-ND ', cdb.secuencia),
            cdbd.abono AS valor,
            cdb.id_asiento
          FROM ct_debito_bancario_detalle cdbd
            JOIN ct_debito_bancario cdb
              ON cdb.id = cdbd.id_debito
            JOIN ct_compras cc
              ON cc.id = cdbd.id_compra
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cdb.id_asiento
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
            JOIN proveedor p
              ON p.id = cdb.id_acreedor
            JOIN ct_caja_banco ccb
              ON ccb.id = cdb.id_banco
          WHERE cc.estado <> '0'
          AND cdb.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          AND cc.proveedor = id_proveedor
          GROUP BY cdbd.id_compra
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            3 AS orden,
            cc.id AS id_compra_,
            cdcem.id,
            'EgMas' AS tipo,
            CONCAT(p.razonsocial, ' # ', ccem.descripcion, ' Ref: ', cdcem.id_secuencia, ' -- Asiento ', ccem.id_asiento_cabecera, ' #Egreso Masivo: ', cdcem.id, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            ccem.fecha_comprobante,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-M ', ccem.secuencia),
            cdcem.abono AS valor,
            ccem.id_asiento_cabecera
          FROM ct_comprobante_egreso_masivo ccem
            JOIN ct_detalle_comprobante_egreso_masivo cdcem
              ON cdcem.id_comprobante = ccem.id
            JOIN ct_compras cc
              ON cc.id = cdcem.id_compra
            JOIN proveedor p
              ON p.id = cdcem.id_proveedor
            JOIN ct_caja_banco ccb
              ON ccb.id = ccem.id_caja_banco
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = ccem.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND ccem.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          AND cc.proveedor = id_proveedor
          GROUP BY cdcem.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            4 AS orden,
            cc.id AS id_compra_,
            ccv.id,
            'CRUV' AS tipo,
            CONCAT(p.razonsocial, ' # ', ccv.detalle, ' Ref: ', cdc.secuencia_factura, ' #Cruce: ', cdc.id_comprobante, ' -- Asiento ', ccv.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cdc.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-CR-AF ', ccv.secuencia),
            cdc.total AS valor,
            ccv.id_asiento_cabecera
          FROM ct_cruce_valores ccv
            JOIN ct_detalle_cruce cdc
              ON cdc.id_comprobante = ccv.id
            JOIN ct_compras cc
              ON cc.id = cdc.id_factura
            JOIN proveedor p
              ON p.id = ccv.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = ccv.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND ccv.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          AND cc.proveedor = id_proveedor
          GROUP BY ccv.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            5 AS orden,
            cc.id AS id_compra_,
            cr.id,
            'Ret' AS tipo,
            CONCAT(p.razonsocial, ' # ', cr.descripcion, ' Ref: ', cc.secuencia_f, ' #Retencion: ', cr.id, ' -- Asiento ', cr.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            cr.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-RE ', cr.secuencia),
            cr.total AS valor,
            cr.id_asiento_cabecera
          FROM ct_retenciones cr
            JOIN ct_compras cc
              ON cc.id = cr.id_compra
            JOIN proveedor p
              ON p.id = cr.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cr.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND cr.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          AND cc.proveedor = id_proveedor
          GROUP BY cr.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            6 AS orden,
            cc.id AS id_compra_,
            cda.id,
            'DbAcr' AS tipo,
            CONCAT(p.razonsocial, ' # ', cda.concepto, ' Ref: ', cc.secuencia_f, ' #Debito: ', cdda.id_debito_acreedores, ' -- Asiento ', cda.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            "",
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('ACR-DB ', cc.secuencia_factura),
            cda.valor_contable AS valor,
            cda.id_asiento_cabecera
          FROM ct_debito_acreedores cda
            JOIN ct_detalle_debito_acreedores cdda
              ON cdda.id_debito_acreedores = cda.id
            JOIN ct_compras cc
              ON cc.id = cdda.id_factura
            JOIN proveedor p
              ON p.id = cda.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = cda.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND cda.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          AND cc.proveedor = id_proveedor
          GROUP BY cda.id
          ORDER BY cc.f_autorizacion DESC)
        UNION ALL
        (SELECT
            7 AS orden,
            cc.id AS id_compra_,
            ccc.id,
            'CruCta' AS tipo,
            CONCAT(p.razonsocial, ' # ', ccc.detalle, ' Ref: ', cc.secuencia_f, ' #Cruce_Cuentas: ', ccc.id, ' -- Asiento ', ccc.id_asiento_cabecera) AS detalle,
            p.id AS RUC,
            p.razonsocial,
            ccc.fecha,
            CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
            CONCAT('CRUCE-CUENTAS ', ccc.secuencia),
            ccc.total AS valor,
            ccc.id_asiento_cabecera
          FROM ct_cruce_cuentas ccc
            JOIN ct_compras cc
              ON cc.id = ccc.id_factura
            JOIN proveedor p
              ON p.id = ccc.id_proveedor
            JOIN ct_asientos_detalle cad
              ON cad.id_asiento_cabecera = ccc.id_asiento_cabecera
            LEFT JOIN plan_cuentas pc
              ON cad.id_plan_cuenta = pc.id
            LEFT JOIN plan_cuentas_empresa pce
              ON pc.id = pce.plan
          WHERE cc.estado <> '0'
          AND ccc.estado <> '0'
          AND cad.descripcion LIKE '%PROVEEDORE%'
          AND cc.f_autorizacion BETWEEN desde AND hasta
          AND cc.id_empresa = id_empresa
          AND cc.proveedor = id_proveedor
          GROUP BY ccc.id
          ORDER BY cc.f_autorizacion DESC)) AS dvp
      ORDER BY dvp.fecha DESC, dvp.id_compra_) AS dvp
    ORDER BY dvp.fecha DESC, dvp.id_compra_;
  END IF;
END
$$

--
-- Create procedure `sp_balance`
--
CREATE
PROCEDURE sp_balance (IN id_empresa varchar(13),
IN desde varchar(10),
IN hasta varchar(10))
BEGIN

  (SELECT
      pe.plan,
      pe.nombre,
      SUM(debe) AS debe,
      SUM(haber) AS haber,
      IF(pe.naturaleza_2 = 1, SUM(IFNULL(haber, 0) - IFNULL(debe, 0)), 0) AS saldo_acreedor,
      IF(pe.naturaleza_2 = 0, SUM(IFNULL(debe, 0) - IFNULL(haber, 0)), 0) AS saldo_deudor,
      pe.naturaleza,
      pe.naturaleza_2,
      (IFNULL(SUM(CASE WHEN MONTH(ac.fecha_asiento) BETWEEN 1 AND 12 THEN (IF(pe.naturaleza_2 = 1, debe - haber, haber - debe)) END), 0)) AS total,
      IF(SUBSTRING(pe.plan, 1, 1) = '1', 'ACTIVOS', IF(SUBSTRING(pe.plan, 1, 1) = '2', 'PASIVOS', 'PATRIMONIO')) AS tipo,
      COALESCE((SELECT
          id
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 1)
        AND id BETWEEN 1 AND 3 LIMIT 1), '') AS id_clase,
      COALESCE((SELECT
          nombre
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 1)
        AND id BETWEEN 1 AND 3 LIMIT 1), '') AS clase,
      COALESCE((SELECT
          id
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 4) LIMIT 1), '') AS id_grupo,
      COALESCE((SELECT
          nombre
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 4) LIMIT 1), '') AS grupo,
      COALESCE((SELECT
          id
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 7) LIMIT 1), '') AS id_cuenta,
      COALESCE((SELECT
          nombre
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 7) LIMIT 1), '') AS cuenta,
      COALESCE((SELECT
          id
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 10) LIMIT 1), (SELECT
          id
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 9) LIMIT 1), '') AS id_subcuenta,
      COALESCE((SELECT
          nombre
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 10) LIMIT 1), (SELECT
          nombre
        FROM plan_cuentas
        WHERE id = SUBSTRING(pe.plan, 1, 9) LIMIT 1), '') AS subcuenta
    FROM ct_asientos_detalle ad
      JOIN ct_asientos_cabecera ac
        ON ad.id_asiento_cabecera = ac.id
      LEFT JOIN plan_cuentas_empresa pe
        ON ad.id_plan_cuenta = pe.id_plan
        AND pe.id_empresa = ac.id_empresa
      LEFT JOIN plan_cuentas pc
        ON ad.id_plan_cuenta = pc.id
    WHERE ac.id_empresa = id_empresa
    AND ac.fecha_asiento < hasta
    AND (pe.plan LIKE '1.%'
    OR pe.plan LIKE '2.%'
    OR pe.plan LIKE '3.%')
    GROUP BY pe.plan
    ORDER BY pe.plan)
  UNION ALL
  (SELECT
      '2.01.07.05.01',
      'PARTICIPACION 15%',
      SUM(debe) AS debe,
      SUM(haber) AS haber,
      IF(pe.naturaleza_2 = 1, SUM(IFNULL(haber, 0) - IFNULL(debe, 0)), 0) AS saldo_acreedor,
      IF(IF(pe.naturaleza_2 = 0, (SUM(IFNULL(debe, 0) - IFNULL(haber, 0)) * 0.15) * -1, 0) > 0, IF(pe.naturaleza_2 = 0, (SUM(IFNULL(debe, 0) - IFNULL(haber, 0)) * 0.15) * -1, 0), 0) AS participacion,
      pe.naturaleza,
      pe.naturaleza_2,
      'total',
      'PASIVOS',
      '2',
      'PASIVOS',
      '2.01',
      '',
      '2.01.07',
      '',
      '2.01.07.05',
      ''
    FROM ct_asientos_detalle ad
      JOIN ct_asientos_cabecera ac
        ON ad.id_asiento_cabecera = ac.id
      LEFT JOIN plan_cuentas_empresa pe
        ON ad.id_plan_cuenta = pe.id_plan
        AND pe.id_empresa = ac.id_empresa
      LEFT JOIN plan_cuentas pc
        ON ad.id_plan_cuenta = pc.id
    WHERE ac.id_empresa = id_empresa
    AND ac.fecha_asiento >= desde
    AND ac.fecha_asiento < hasta
    AND (pe.plan LIKE "4.%"
    OR pe.plan LIKE "5.%"))
  UNION ALL
  (SELECT
      '3.07.01',
      'UTILIDAD DEL EJERCICIO',
      IFNULL(SUM(debe), 0) AS debe,
      IFNULL(SUM(haber), 0) AS haber,
      IF(pe.naturaleza_2 = 1, SUM(IFNULL(haber, 0) - IFNULL(debe, 0)), 0) AS saldo_acreedor,

      -- IF(pe.naturaleza_2=0,(sum(IFNULL(debe,0)-IFNULL(haber,0)))*-1,0) as UtilidadBruta,

      -- IF(IF(pe.naturaleza_2=0,(sum(IFNULL(debe,0)-IFNULL(haber,0))*0.15)*-1,0)>0,IF(pe.naturaleza_2=0,(sum(IFNULL(debe,0)-IFNULL(haber,0))*0.15)*-1,0),0) as participacion,
      -- IF(pe.naturaleza_2=0,(sum(IFNULL(debe,0)-IFNULL(haber,0)))*-1,0)-IF(pe.naturaleza_2=0,(sum(IFNULL(debe,0)-IFNULL(haber,0))*0.15)*-1,0) as UtilidadNeta,

      -- (select tipo_rimpe from de_empresa where id_empresa=ac.id_empresa) as tipo_rimpe,

      -- iF((select tipo_rimpe from de_empresa where id_empresa=ac.id_empresa)=0,'0',
      -- iF((select tipo_rimpe from de_empresa where id_empresa=ac.id_empresa)=1,'1',
      -- iF((select tipo_rimpe from de_empresa where id_empresa=ac.id_empresa)=2,
      --  (select ((IF(pe.naturaleza_2=0,(sum(IFNULL(debe,0)-IFNULL(haber,0)))*-1,0)-IF(pe.naturaleza_2=0,(sum(IFNULL(debe,0)-IFNULL(haber,0))*0.15)*-1,0))*porcentaje)/100 from ct_porcentaje_renta where id_empresa=ac.id_empresa and anio=2022),
      -- ''))) as impuestoCausado,

      (IF(pe.naturaleza_2 = 0, (SUM(IFNULL(debe, 0) - IFNULL(haber, 0))) * -1, 0) - IF(pe.naturaleza_2 = 0, (SUM(IFNULL(debe, 0) - IFNULL(haber, 0)) * 0.15) * -1, 0)) -
      IF((SELECT
          tipo_rimpe
        FROM de_empresa
        WHERE id_empresa = ac.id_empresa) = 0, '0',
      IF((SELECT
          tipo_rimpe
        FROM de_empresa
        WHERE id_empresa = ac.id_empresa) = 1, '1',
      IF((SELECT
          tipo_rimpe
        FROM de_empresa
        WHERE id_empresa = ac.id_empresa) = 2, (SELECT
          ((IF(pe.naturaleza_2 = 0, (SUM(IFNULL(debe, 0) - IFNULL(haber, 0))) * -1, 0) - IF(pe.naturaleza_2 = 0, (SUM(IFNULL(debe, 0) - IFNULL(haber, 0)) * 0.15) * -1, 0)) * porcentaje) / 100
        FROM ct_porcentaje_renta
        WHERE id_empresa = ac.id_empresa
        AND anio = YEAR(desde)),
      ''))) AS utilidad,

      pe.naturaleza,
      pe.naturaleza_2,
      'total',
      'PATRIMONIO',
      '3',
      'PATRIMONIO',
      '3.01',
      '',
      '3.01.07',
      '',
      '3.01.07.05',
      ''
    FROM ct_asientos_detalle ad
      JOIN ct_asientos_cabecera ac
        ON ad.id_asiento_cabecera = ac.id
      LEFT JOIN plan_cuentas_empresa pe
        ON ad.id_plan_cuenta = pe.id_plan
        AND pe.id_empresa = ac.id_empresa
      LEFT JOIN plan_cuentas pc
        ON ad.id_plan_cuenta = pc.id
    WHERE ac.id_empresa = id_empresa
    AND ac.fecha_asiento >= desde
    AND ac.fecha_asiento < hasta
    AND (pe.plan LIKE "4.%"
    OR pe.plan LIKE "5.%")
    ORDER BY pe.plan ASC);
END
$$

DELIMITER ;

