--
-- Create view `vt_inventario`
--
CREATE
VIEW vt_inventario
AS
SELECT
  `i`.`id_bodega` AS `id_bodega`,
  `i`.`id_producto` AS `id_producto`,
  `p`.`nombre` AS `nombre`,
  SUM(`i`.`existencia`) AS `existencias`
FROM (`inv_inventario` `i`
  JOIN `producto` `p`
    ON (`p`.`id` = `i`.`id_producto`))
GROUP BY `i`.`id_bodega`,
         `i`.`id_producto`;

