--
-- Create table `historiaclinica`
--
CREATE TABLE historiaclinica (
  hcid int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  id_agenda int(11) UNSIGNED NOT NULL,
  id_paciente varchar(13) NOT NULL,
  id_seguro int(11) NOT NULL,
  id_subseguro int(11) DEFAULT NULL,
  copago tinyint(4) DEFAULT 0,
  id_doctor1 varchar(13) NOT NULL,
  id_doctor2 varchar(13) DEFAULT NULL,
  id_doctor3 varchar(13) DEFAULT NULL,
  evolucion text DEFAULT NULL,
  observaciones varchar(255) DEFAULT NULL,
  receta text DEFAULT NULL,
  codigo varchar(60) DEFAULT NULL,
  verificar tinyint(4) DEFAULT 0,
  peso float DEFAULT 0,
  altura float DEFAULT 0,
  temperatura float DEFAULT 0,
  presion varchar(40) DEFAULT '0',
  o2 varchar(30) DEFAULT '0',
  perimetro float DEFAULT 0,
  pulso float DEFAULT 0,
  fecha_codigo datetime DEFAULT NULL,
  estado tinyint(4) DEFAULT 0 COMMENT '0 pendiente de atención 1 atendido',
  fecha_atencion timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  id_cie_10 varchar(10) DEFAULT NULL,
  estad tinyint(4) DEFAULT 0,
  id_usuariocrea varchar(13) NOT NULL,
  id_usuariomod varchar(13) NOT NULL,
  ip_creacion varchar(40) NOT NULL,
  ip_modificacion varchar(40) NOT NULL,
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP() ON UPDATE CURRENT_TIMESTAMP,
  deleted_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  parentesco varchar(255) DEFAULT NULL,
  id_usuario varchar(13) DEFAULT NULL,
  examenes_realizar mediumtext DEFAULT NULL,
  observaciones_enfermeria mediumtext DEFAULT NULL,
  PRIMARY KEY (hcid)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 343,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

