  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP() ON UPDATE CURRENT_TIMESTAMP,
  completo tinyint(4) DEFAULT 0,
  numorden_iess varchar(255) DEFAULT NULL,
  historia_iess varchar(255) DEFAULT NULL,
  estado_orden_iess tinyint(4) DEFAULT 0,
  codigo varchar(10) DEFAULT NULL,
  enviado_doctor_externo tinyint(4) NOT NULL DEFAULT 0 COMMENT '1: enviado; 0: no enviado',
  pres_dom tinyint(4) DEFAULT 0,
  pago_online tinyint(4) DEFAULT 0,
