  comprobante varchar(255) DEFAULT NULL,
  fecha_envio datetime DEFAULT NULL,
  orden_agrupado int(11) DEFAULT NULL,
  venta_gastro int(11) DEFAULT NULL,
  numero_oda varchar(255) DEFAULT NULL,
  cobrar_pac_pct decimal(10, 2) DEFAULT 100.00,
  valor_con_oda decimal(10, 4) DEFAULT 0.0000,
  total_con_oda decimal(10, 4) DEFAULT 0.0000,
  estado_venta tinyint(4) NOT NULL DEFAULT 0,
