  leido_bd tinyint(4) NOT NULL DEFAULT 0,
  otros varchar(255) DEFAULT NULL,
  prioridad_orden tinyint(4) NOT NULL DEFAULT 0,
  id_agenda_consulta int(5) UNSIGNED DEFAULT NULL,
