--
-- Create view `BIOPSIAS`
--
CREATE
VIEW BIOPSIAS
AS
SELECT
  `hpf`.`id` AS `id`,
  `hpf`.`id_hc_procedimientos` AS `id_hc_procedimientos`,
  `hpf`.`id_procedimiento` AS `id_procedimiento`,
  `hpf`.`created_at` AS `created_at`,
  `hpf`.`updated_at` AS `updated_at`,
  `hpf`.`id_usuariocrea` AS `id_usuariocrea`,
  `hpf`.`id_usuariomod` AS `id_usuariomod`,
  `hpf`.`ip_creacion` AS `ip_creacion`,
  `hpf`.`ip_modificacion` AS `ip_modificacion`
FROM `hc_procedimiento_final` `hpf`
WHERE `hpf`.`id_procedimiento` = 19;

