--
-- Create view `control_kardex_usos`
--
CREATE
VIEW control_kardex_usos
AS
SELECT
  `iis`.`id_producto` AS `id_producto`,
  `pr`.`nombre` AS `nombre`,
  `iis`.`id_bodega` AS `id_bodega`,
  `iis`.`serie` AS `serie`,
  `iis`.`cantidad_usos_kardex` AS `cantidad_usos_kardex`,
  `ikn`.`tipo` AS `tipo`,
  `ikn`.`cantidad` AS `cantidad`,
  SUM(`ikn`.`cantidad`) AS `sum(ikn.cantidad)`
FROM ((`inv_inventario_serie` `iis`
  JOIN `producto` `pr`
    ON (`pr`.`id` = `iis`.`id_producto`))
  JOIN `inv_kardex_nuevo` `ikn`
    ON (`ikn`.`serie` = `iis`.`serie`
    AND `ikn`.`id_bodega` = `iis`.`id_bodega`))
WHERE `iis`.`cantidad_usos_kardex` IS NOT NULL
GROUP BY `ikn`.`serie`,
         `ikn`.`tipo`
ORDER BY `ikn`.`serie`, `ikn`.`tipo`;

--
-- Create view `control_existencias`
--
CREATE
VIEW control_existencias
AS
SELECT
  `ii`.`id` AS `id`,
  `ii`.`id_producto` AS `id_producto`,
  `ii`.`id_bodega` AS `id_bodega`,
  `ii`.`existencia` AS `cantidad_inv`,
  SUM(`iis`.`existencia`) AS `cantidad_serie`,
  `p`.`nombre` AS `nombre`
FROM ((`inv_inventario` `ii`
  LEFT JOIN `inv_inventario_serie` `iis`
    ON (`ii`.`id` = `iis`.`id_inv_inventario`))
  JOIN `producto` `p`
    ON (`ii`.`id_producto` = `p`.`id`))
GROUP BY `iis`.`id_inv_inventario`;

