--
-- Create view `cuadre_pedido`
--
CREATE
VIEW cuadre_pedido
AS
SELECT
  `p`.`id` AS `id_pedido`,
  `p`.`fecha` AS `fecha`,
  `p`.`total` AS `total`,
  `p`.`subtotal_0` AS `subtotal_0`,
  `p`.`subtotal_12` AS `subtotal_12`,
  `p`.`iva` AS `iva`,
  `p`.`descuento` AS `descuento`,
  SUM(`dm`.`subtotal`) AS `dmsubtotal`,
  SUM(`dm`.`descuento`) AS `dmdescuento`,
  SUM(`dm`.`iva`) AS `dmiva`,
  SUM(`dm`.`total`) AS `dmtotal`,
  `icm`.`id_asiento` AS `id_asiento`
FROM ((`pedido` `p`
  JOIN `inv_det_movimientos` `dm`
    ON (`dm`.`id_pedido` = `p`.`id`))
  JOIN `inv_cab_movimientos` `icm`
    ON (`dm`.`id_inv_cab_movimientos` = `icm`.`id`))
GROUP BY `p`.`id`;

