--
-- Create view `vt_kardex`
--
CREATE
VIEW vt_kardex
AS
SELECT
  `k`.`id_bodega` AS `id_bodega`,
  `k`.`id_producto` AS `id_producto`,
  `p`.`nombre` AS `nombre`,
  `k`.`tipo` AS `tipo`,
  SUM(`k`.`cantidad`) AS `cantidad`
FROM (`inv_kardex` `k`
  JOIN `producto` `p`
    ON (`p`.`id` = `k`.`id_producto`))
GROUP BY `k`.`id_bodega`,
         `k`.`id_producto`,
         `k`.`tipo`;

--
-- Create view `vt_control_kardex_inventario`
--
CREATE
VIEW vt_control_kardex_inventario
AS
SELECT
  `i`.`id_bodega` AS `id_bodega`,
  `i`.`id_producto` AS `id_producto`,
  `i`.`nombre` AS `nombre`,
  `inv`.`id_empresa` AS `id_empresa`,
  `i`.`existencias` AS `existencias`,
  (SELECT
      `k1`.`cantidad`
    FROM `vt_kardex` `k1`
    WHERE `k1`.`id_bodega` = `i`.`id_bodega`
    AND `k1`.`id_producto` = `i`.`id_producto`
    AND `k1`.`tipo` = 'I') AS `Ing`,
  (SELECT
      `k1`.`cantidad`
    FROM `vt_kardex` `k1`
    WHERE `k1`.`id_bodega` = `i`.`id_bodega`
    AND `k1`.`id_producto` = `i`.`id_producto`
    AND `k1`.`tipo` = 'E') AS `Egr`,
  (SELECT
      `k1`.`cantidad`
    FROM `vt_kardex` `k1`
    WHERE `k1`.`id_bodega` = `i`.`id_bodega`
    AND `k1`.`id_producto` = `i`.`id_producto`
    AND `k1`.`tipo` = 'T') AS `Tra`,
  (SELECT
      `k1`.`cantidad`
    FROM `vt_kardex` `k1`
    WHERE `k1`.`id_bodega` = `i`.`id_bodega`
    AND `k1`.`id_producto` = `i`.`id_producto`
    AND `k1`.`tipo` = 'I') - (SELECT
      `k1`.`cantidad`
    FROM `vt_kardex` `k1`
    WHERE `k1`.`id_bodega` = `i`.`id_bodega`
    AND `k1`.`id_producto` = `i`.`id_producto`
    AND `k1`.`tipo` = 'E') - (SELECT
      `k1`.`cantidad`
    FROM `vt_kardex` `k1`
    WHERE `k1`.`id_bodega` = `i`.`id_bodega`
    AND `k1`.`id_producto` = `i`.`id_producto`
    AND `k1`.`tipo` = 'T') AS `t_k`
FROM (`vt_inventario` `i`
  JOIN `inv_inventario` `inv`
    ON (`inv`.`id_bodega` = `i`.`id_bodega`
    AND `inv`.`id_producto` = `i`.`id_producto`));

--
-- Create view `control_kardex_producto`
--
CREATE
VIEW control_kardex_producto
AS
SELECT
  `s`.`id_bodega` AS `id_bodega`,
  `s`.`serie` AS `serie`,
  `p`.`nombre` AS `nombre`,
  `p`.`id` AS `id_producto`,
  (SELECT
      SUM(`k1`.`cantidad`)
    FROM (`inv_kardex` `k1`
      JOIN `inv_det_movimientos` `d1`
        ON (`d1`.`id` = `k1`.`id_inv_det_movimientos`))
    WHERE `k1`.`id_bodega` = 2
    AND `k1`.`tipo` = 'I'
    AND `d1`.`serie` = `s`.`serie`) AS `ing`,
  (SELECT
      SUM(`k`.`cantidad`)
    FROM (`inv_kardex` `k`
      JOIN `inv_det_movimientos` `d`
        ON (`d`.`id` = `k`.`id_inv_det_movimientos`))
    WHERE `k`.`id_bodega` = 2
    AND `k`.`tipo` = 'E'
    AND `d`.`serie` = `s`.`serie`) AS `egr`,
  (SELECT
      SUM(`k`.`cantidad`)
    FROM (`inv_kardex` `k`
      JOIN `inv_det_movimientos` `d`
        ON (`d`.`id` = `k`.`id_inv_det_movimientos`))
    WHERE `k`.`id_bodega` = 2
    AND `k`.`tipo` = 'T'
    AND `d`.`serie` = `s`.`serie`) AS `tra`
FROM (`inv_inventario_serie` `s`
  JOIN `producto` `p`
    ON (`p`.`id` = `s`.`id_producto`))
WHERE `s`.`id_bodega` = '2';

--
-- Create view `control_kardex_empresa`
--
CREATE
VIEW control_kardex_empresa
AS
SELECT
  `s`.`id_bodega` AS `id_bodega`,
  `s`.`serie` AS `serie`,
  `p`.`nombre` AS `nombre`,
  `p`.`id` AS `id_producto`,
  `s`.`id_empresa` AS `id_empresa`,
  (SELECT
      SUM(`k1`.`cantidad`)
    FROM (`inv_kardex` `k1`
      JOIN `inv_det_movimientos` `d1`
        ON (`d1`.`id` = `k1`.`id_inv_det_movimientos`))
    WHERE `k1`.`id_bodega` = 2
    AND `k1`.`tipo` = 'I'
    AND `d1`.`serie` = `s`.`serie`) AS `ing`,
  (SELECT
      SUM(`k`.`cantidad`)
    FROM (`inv_kardex` `k`
      JOIN `inv_det_movimientos` `d`
        ON (`d`.`id` = `k`.`id_inv_det_movimientos`))
    WHERE `k`.`id_bodega` = 2
    AND `k`.`tipo` = 'E'
    AND `d`.`serie` = `s`.`serie`) AS `egr`,
  (SELECT
      SUM(`k`.`cantidad`)
    FROM (`inv_kardex` `k`
      JOIN `inv_det_movimientos` `d`
        ON (`d`.`id` = `k`.`id_inv_det_movimientos`))
    WHERE `k`.`id_bodega` = 2
    AND `k`.`tipo` = 'T'
    AND `d`.`serie` = `s`.`serie`) AS `tra`
FROM (`inv_inventario_serie` `s`
  JOIN `producto` `p`
    ON (`p`.`id` = `s`.`id_producto`))
WHERE `s`.`id_bodega` = '2';

--
-- Create view `control_kardex`
--
CREATE
VIEW control_kardex
AS
SELECT
  `s`.`id_bodega` AS `id_bodega`,
  `s`.`serie` AS `serie`,
  `p`.`nombre` AS `nombre`,
  (SELECT
      SUM(`k1`.`cantidad`)
    FROM (`inv_kardex` `k1`
      JOIN `inv_det_movimientos` `d1`
        ON (`d1`.`id` = `k1`.`id_inv_det_movimientos`))
    WHERE `k1`.`id_bodega` = 2
    AND `k1`.`tipo` = 'I'
    AND `d1`.`serie` = `s`.`serie`) AS `ing`,
  (SELECT
      SUM(`k`.`cantidad`)
    FROM (`inv_kardex` `k`
      JOIN `inv_det_movimientos` `d`
        ON (`d`.`id` = `k`.`id_inv_det_movimientos`))
    WHERE `k`.`id_bodega` = 2
    AND `k`.`tipo` = 'E'
    AND `d`.`serie` = `s`.`serie`) AS `egr`,
  (SELECT
      SUM(`k`.`cantidad`)
    FROM (`inv_kardex` `k`
      JOIN `inv_det_movimientos` `d`
        ON (`d`.`id` = `k`.`id_inv_det_movimientos`))
    WHERE `k`.`id_bodega` = 2
    AND `k`.`tipo` = 'T'
    AND `d`.`serie` = `s`.`serie`) AS `tra`
FROM (`inv_inventario_serie` `s`
  JOIN `producto` `p`
    ON (`p`.`id` = `s`.`id_producto`))
WHERE `s`.`id_bodega` = '2';

