  estado_as400 tinyint(4) DEFAULT 0,
  id_examen int(11) DEFAULT NULL,
  id_agrupador_privado int(11) DEFAULT NULL,
  id_agrupador_publico int(11) DEFAULT NULL,
  fecha_anterior timestamp NULL DEFAULT NULL,
  PRIMARY KEY (id)
