AVG_ROW_LENGTH = 2197,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create view `PACS_CITOMEGA`
--
CREATE
VIEW PACS_CITOMEGA
AS
SELECT
  `eo`.`id_paciente` AS `id_paciente`,
  `er`.`created_at` AS `created_at`,
  `er`.`valor` AS `valor`
FROM (`examen_resultado` `er`
  JOIN `examen_orden` `eo`
    ON (`eo`.`id` = `er`.`id_orden`))
WHERE `er`.`id_parametro` = '554'
AND (`er`.`valor` LIKE '%*%'
OR `er`.`valor` > 2);

