ENGINE = INNODB,
AVG_ROW_LENGTH = 1820,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `sp_proveedores_deudas_pendientes`
--
CREATE
PROCEDURE sp_proveedores_deudas_pendientes (IN id_empresa varchar(20), IN fecha_desde datetime, IN fecha_hasta datetime, IN id_proveedor varchar(13))
BEGIN

  SELECT
    *,
    CASE WHEN tipo = 'Factura' THEN total_final ELSE 0 END AS deuda,
    CASE WHEN tipo != 'Factura' THEN total_final ELSE 0 END AS abono,
    SUM(CASE WHEN tipo = 'Factura' THEN total_final ELSE -total_final END) OVER (PARTITION BY dp.id_empresa ORDER BY dp.id, dp.identificacion, dp.orden) AS saldo,
    SUM(CASE WHEN tipo = 'Factura' THEN total_final ELSE 0 END) OVER (PARTITION BY dp.id_empresa ORDER BY dp.id, dp.identificacion, dp.orden) AS total_deudas,
    SUM(CASE WHEN tipo != 'Factura' THEN total_final ELSE 0 END) OVER (PARTITION BY dp.id_empresa ORDER BY dp.id, dp.identificacion, dp.orden) AS total_abonos
  FROM (SELECT
      0 AS orden,
      'Factura' AS tipo,
      c.id,
      c.serie,
      c.secuencia_f,
      c.fecha AS fecha_compra,
      0 AS fecha_documento,
      p.id AS identificacion,
      p.razonsocial,
      c.subtotal_0,
      c.subtotal_12,
      c.subtotal,
      c.iva_total,
      c.total_final,
      c.valor_contable,
      c.id_empresa,
      CONCAT(p.razonsocial, ' Fact: # ', c.numero, ' Ref: ', c.id, ' -- Asiento ', c.id_asiento_cabecera) AS detalle,
      c.id_asiento_cabecera AS id_asiento,
      CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
      CONCAT('COM-FA ', c.secuencia_f) AS comprobante
    FROM proveedor AS p
      JOIN ct_compras AS c
        ON p.id = c.proveedor
      LEFT JOIN ct_asientos_detalle cad
        ON c.id_asiento_cabecera = cad.id_asiento_cabecera
        AND cad.descripcion LIKE '%PROVEE%'
      LEFT JOIN plan_cuentas pc
        ON cad.id_plan_cuenta = pc.id
      LEFT JOIN plan_cuentas_empresa pce
        ON pc.id = pce.plan
        AND pce.id_empresa = id_empresa
    WHERE c.estado != 0
    UNION ALL

    SELECT
      1 AS orden,
      'CE' AS tipo,
      c.id,
      0 AS serie,
      ce.id_secuencia,
      c.fecha AS fecha_compra,
      ce.fecha_comprobante AS fecha_documento,
      p.id AS identificacion,
      p.razonsocial,
      0 AS subtotal_0,
      0 AS subtotal_12,
      0 AS iva,
      0 AS total,
      dc.abono,
      c.valor_contable,
      ce.id_empresa,
      CONCAT(p.razonsocial, ' # ', dc.observacion, ' Ref: ', dc.id_secuencia, ' -- Asiento ', ce.id_asiento_cabecera, ' #Egreso: ', dc.id_comprobante, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
      ce.id_asiento_cabecera AS id_asiento,
      CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
      CONCAT('ACR-EG ', ce.secuencia) AS comprobante
    FROM ct_detalle_comprobante_egreso AS dc
      JOIN ct_compras AS c
        ON dc.id_compra = c.id
      JOIN proveedor AS p
        ON c.proveedor = p.id
      JOIN ct_comprobante_egreso ce
        ON dc.id_comprobante = ce.id
      JOIN ct_caja_banco ccb
        ON ccb.id = ce.id_caja_banco
      LEFT JOIN ct_asientos_detalle cad
        ON ce.id_asiento_cabecera = cad.id_asiento_cabecera
        AND cad.descripcion LIKE '%PROVEE%'
      LEFT JOIN plan_cuentas pc
        ON cad.id_plan_cuenta = pc.id
      LEFT JOIN plan_cuentas_empresa pce
        ON pc.id = pce.plan
        AND pce.id_empresa = id_empresa
    WHERE ce.estado != 0

    UNION ALL

    SELECT
      2 AS orden,
      'RETENCIONES' AS tipo,
      c.id,
      0 AS serie,
      ct.secuencia,
      c.fecha AS fecha_compra,
      ct.fecha AS fecha_documento,
      p.id AS identificacion,
      p.razonsocial,
      0 AS subtotal_0, --
      0 AS subtotal_12, --
      0 AS subtotal,
      0 AS iva,
      (ct.valor_fuente + ct.valor_iva),
      c.valor_contable,
      ct.id_empresa,
      -- aqui
      CONCAT(p.razonsocial, ' # ', ct.descripcion, ' Ref: ', c.secuencia_f, ' #Retencion: ', ct.id, ' -- Asiento ', ct.id_asiento_cabecera) AS detalle,
      ct.id_asiento_cabecera AS id_asiento,
      CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
      CONCAT('ACR-RE ', ct.secuencia) AS comprobante
    FROM ct_retenciones AS ct
      JOIN ct_compras AS c
        ON ct.id_compra = c.id
      JOIN proveedor AS p
        ON c.proveedor = p.id
      LEFT JOIN ct_asientos_detalle cad
        ON c.id_asiento_cabecera = cad.id_asiento_cabecera
        AND cad.descripcion LIKE '%PROVEE%'
      LEFT JOIN plan_cuentas pc
        ON cad.id_plan_cuenta = pc.id
      LEFT JOIN plan_cuentas_empresa pce
        ON pc.id = pce.plan
        AND pce.id_empresa = id_empresa
    WHERE ct.estado <> 0

    UNION ALL

    SELECT
      3 AS orden,
      'CRUCE DE CUENTAS' AS tipo,
      c.id,
      0 AS serie,
      ccc.secuencia,
      c.fecha AS fecha_compra,
      ccc.fecha_pago AS fecha_documento,
      p.id AS identificacion,
      p.razonsocial,
      0 AS subtotal_0,
      0 AS subtotal_12,
      0 AS iva,
      ccc.total_disponible,
      0 AS abono,
      ccc.total_disponible,
      ccc.id_empresa,
      CONCAT(p.razonsocial, ' # ', ccc.detalle, ' Ref: ', cdc.secuencia_factura, ' #Cruce: ', cdc.id_comprobante, ' -- Asiento ', ccc.id_asiento_cabecera) AS detalle,
      ccc.id_asiento_cabecera AS id_asiento,
      CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
      CONCAT('CRUCE-CUENTAS ', ccc.secuencia) AS comprobante
    FROM ct_cruce_valores ccc
      JOIN ct_detalle_cruce AS cdc
        ON ccc.id = cdc.id_comprobante
      JOIN ct_compras AS c
        ON cdc.id_factura = c.id
      JOIN proveedor AS p
        ON c.proveedor = p.id
      LEFT JOIN ct_asientos_detalle cad
        ON c.id_asiento_cabecera = cad.id_asiento_cabecera
        AND cad.descripcion LIKE '%PROVEE%'
      LEFT JOIN plan_cuentas pc
        ON cad.id_plan_cuenta = pc.id
      LEFT JOIN plan_cuentas_empresa pce
        ON pc.id = pce.plan
        AND pce.id_empresa = id_empresa
    WHERE ccc.estado <> 0
    UNION ALL

    SELECT
      4 AS orden,
      'DEBITO ACREEDORES' AS tipo,
      c.id,
      cda.serie,
      cda.secuencia,
      c.fecha AS fecha_compra,
      cda.fecha_factura AS fecha_documento,
      p.id AS identificacion,
      p.razonsocial,
      0 AS subtotal_0,
      0 AS subtotal_12,
      0 AS iva,
      ctda.total_factura,
      0 AS abono,
      ctda.total_factura,
      cda.id_empresa,
      CONCAT(p.razonsocial, ' # ', ctda.concepto, ' Ref: ', c.secuencia_f, ' #Debito: ', ctda.id_debito_acreedores, ' -- Asiento ', cda.id_asiento_cabecera) AS detalle,
      cda.id_asiento_cabecera AS id_asiento,
      CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
      CONCAT('ACR-DB ', c.secuencia_factura) AS comprobante
    FROM ct_debito_acreedores cda
      JOIN ct_detalle_debito_acreedores AS ctda
        ON cda.id = ctda.id_debito_acreedores
      JOIN ct_compras AS c
        ON ctda.id_factura = c.id
      JOIN proveedor AS p
        ON c.proveedor = p.id
      LEFT JOIN ct_asientos_detalle cad
        ON c.id_asiento_cabecera = cad.id_asiento_cabecera
        AND cad.descripcion LIKE '%PROVEE%'
      LEFT JOIN plan_cuentas pc
        ON cad.id_plan_cuenta = pc.id
      LEFT JOIN plan_cuentas_empresa pce
        ON pc.id = pce.plan
        AND pce.id_empresa = id_empresa
    WHERE cda.estado <> 0

    UNION ALL

    SELECT
      5 AS orden,
      'CREDITO ACRREDORES' AS tipo,
      c.id,
      cca.serie,
      cca.secuencia,
      c.fecha AS fecha_compra,
      cca.fecha AS fecha_documento,
      p.id AS identificacion,
      p.razonsocial,
      cca.subtotal_0,
      cca.subtotal_12,
      cca.impuesto,
      cca.subtotal,
      0 AS abono,
      cca.valor_contable,
      cca.id_empresa,
      CONCAT(p.razonsocial, ' Fact: # ', c.numero, ' Ref: ', c.id, ' -- Asiento ', c.id_asiento_cabecera) AS detalle,
      cca.id_asiento_cabecera AS id_asiento,
      CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
      CONCAT('ACR-ACR ', c.secuencia_factura) AS comprobante
    FROM ct_credito_acreedores AS cca
      JOIN ct_compras AS c
        ON cca.id_compra = c.id
      JOIN proveedor AS p
        ON c.proveedor = p.id
      JOIN ct_detalle_credito_acreedores ctca
        ON ctca.id_debito = cca.id
      LEFT JOIN ct_asientos_detalle cad
        ON c.id_asiento_cabecera = cad.id_asiento_cabecera
        AND cad.descripcion LIKE '%PROVEE%'
      LEFT JOIN plan_cuentas pc
        ON cad.id_plan_cuenta = pc.id
      LEFT JOIN plan_cuentas_empresa pce
        ON pc.id = pce.plan
        AND pce.id_empresa = id_empresa
    WHERE cca.estado <> 0

    UNION ALL

    SELECT
      6 AS orden,
      'DEBITO BANCARIO' AS tipo,
      c.id,
      0 AS serie,
      cdb.secuencia,
      c.fecha AS fecha_compra,
      cdb.fecha AS fecha_documento,
      p.id AS identificacion,
      p.razonsocial,
      0 AS subtotal_0,
      0 AS subtotal_12,
      0 AS impuesto,
      cdb.valor,
      cdbd.abono,
      cdb.valor,
      cdb.id_empresa,
      CONCAT(p.razonsocial, ' # ', cdb.concepto, ' Ref: ', cdbd.numero, ' -- Asientos ', cdb.id_asiento, ' #Debito: ', cdb.id, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
      cdb.id_asiento AS id_asiento,
      CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
      CONCAT('BAN-ND ', cdb.secuencia)
    FROM ct_debito_bancario_detalle AS cdbd
      JOIN ct_compras AS c
        ON cdbd.id_compra = c.id
      JOIN proveedor AS p
        ON c.proveedor = p.id
      JOIN ct_debito_bancario cdb
        ON cdbd.id_debito = cdb.id
      JOIN ct_caja_banco ccb
        ON ccb.id = cdb.id_banco
      LEFT JOIN ct_asientos_detalle cad
        ON c.id_asiento_cabecera = cad.id_asiento_cabecera
        AND cad.descripcion LIKE '%PROVEE%'
      LEFT JOIN plan_cuentas pc
        ON cad.id_plan_cuenta = pc.id
      LEFT JOIN plan_cuentas_empresa pce
        ON pc.id = pce.plan
        AND pce.id_empresa = id_empresa
    WHERE cdb.estado <> 0

    UNION ALL

    SELECT
      7 AS orden,
      'COMPROBANTE EGRESO MASIVO' AS tipo,
      c.id,
      0 AS serie,
      ctem.secuencia,
      c.fecha AS fecha_compra,
      ctem.fecha_comprobante AS fecha_documento,
      p.id AS identificacion,
      p.razonsocial,
      0 AS subtotal_0,
      0 AS subtotal_12,
      0 AS impuesto,
      0 AS valor,
      cdcem.abono,
      0 AS valor,
      ctem.id_empresa,
      CONCAT(p.razonsocial, ' # ', ctem.descripcion, ' Ref: ', cdcem.id_secuencia, ' -- Asiento ', ctem.id_asiento_cabecera, ' #Egreso Masivo: ', cdcem.id, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
      ctem.id_asiento_cabecera AS id_asiento,
      CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
      CONCAT('ACR-M ', ctem.secuencia)
    FROM ct_comprobante_egreso_masivo ctem
      JOIN ct_detalle_comprobante_egreso_masivo AS cdcem
        ON ctem.id = cdcem.id_comprobante
      JOIN ct_compras AS c
        ON cdcem.id_compra = c.id
      JOIN proveedor AS p
        ON c.proveedor = p.id
      JOIN ct_caja_banco ccb
        ON ccb.id = ctem.id_caja_banco
      LEFT JOIN ct_asientos_detalle cad
        ON c.id_asiento_cabecera = cad.id_asiento_cabecera
        AND cad.descripcion LIKE '%PROVEE%'
      LEFT JOIN plan_cuentas pc
        ON cad.id_plan_cuenta = pc.id
      LEFT JOIN plan_cuentas_empresa pce
        ON pc.id = pce.plan
        AND pce.id_empresa = id_empresa
    WHERE ctem.estado <> 0) AS dp
  WHERE (id_proveedor IS NULL
  OR dp.identificacion = id_proveedor)
  AND dp.tipo = 'Factura'
  AND (dp.fecha_compra BETWEEN fecha_desde AND fecha_hasta)
  ORDER BY dp.id, dp.identificacion, dp.orden;
END
$$

--
-- Create procedure `sp_proveedores_deudas_pagos`
--
CREATE
PROCEDURE sp_proveedores_deudas_pagos (IN id_empresa varchar(255), IN desde varchar(255), IN hasta varchar(255), IN id_proveedor varchar(255))
BEGIN
  SET @saldo := 0;
  SELECT
    *,
    CASE WHEN tipo = 'Factura' THEN total_final ELSE 0 END AS deuda,
    CASE WHEN tipo != 'Factura' THEN total_final ELSE 0 END AS abono,
    SUM(CASE WHEN tipo = 'Factura' THEN total_final ELSE -total_final END) OVER (PARTITION BY dvp.id_empresa, idc ORDER BY dvp.idc, dvp.id_proveedor, orden) AS saldo,
    SUM(CASE WHEN tipo = 'Factura' THEN total_final ELSE 0 END) OVER (PARTITION BY dvp.id_empresa ORDER BY dvp.idc, dvp.id_proveedor, orden) AS deuda_total,
    SUM(CASE WHEN tipo != 'Factura' THEN total_final ELSE 0 END) OVER (PARTITION BY dvp.id_empresa ORDER BY dvp.idc, dvp.id_proveedor, orden) AS abono_total
  FROM ((SELECT
        '' aux,
        0 orden,
        c.id_asiento_cabecera AS id_asiento,
        CONCAT(p.razonsocial, ' Fact: # ', c.numero, ' Ref: ', c.id) AS detalle,
        CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion) AS cuenta,
        CONCAT('COM-FA ', c.secuencia_f, ' | Ref: ', c.id) AS Comprobante,
        pce.plan,
        pc.nombre,
        c.id AS idc,
        'Factura' tipo,
        c.fecha,
        c.fecha AS fecha_documento,
        c.numero,
        p.id AS id_proveedor,
        p.razonsocial,
        c.subtotal_0,
        c.subtotal_12,
        c.descuento,
        c.subtotal,
        c.iva_total,
        c.total_final,
        c.id_empresa
      FROM proveedor p
        JOIN ct_compras c
          ON p.id = c.proveedor
        LEFT JOIN ct_asientos_detalle cad
          ON c.id_asiento_cabecera = cad.id_asiento_cabecera
          AND cad.descripcion LIKE '%PROVEE%'
        LEFT JOIN plan_cuentas pc
          ON cad.id_plan_cuenta = pc.id
        LEFT JOIN plan_cuentas_empresa pce
          ON pc.id = pce.plan
          AND pce.id_empresa = id_empresa
      WHERE c.estado != 0)
    UNION ALL
    (SELECT DISTINCT
        (co.id),
        1 orden,
        c.id_asiento_cabecera,
        CONCAT(p.razonsocial, ' # ', dc.observacion, ' Ref: ', dc.id_secuencia, ' #Egreso: ', dc.id_comprobante, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
        CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
        CONCAT('ACR-EG ', c.secuencia, ' | Ref: ', c.id),
        pce.plan,
        pc.nombre,
        co.id AS idc0,
        'COMP-EGR' tipo,
        co.fecha,
        c.fecha_comprobante AS fecha_documento,
        secuencia,
        p.id AS id_proveedor,
        p.razonsocial,
        0 subtotal_0,
        0 subtotal_12,
        0 descuento,
        0 subtotal,
        0 iva_total,
        dc.abono,
        c.id_empresa
      FROM ct_detalle_comprobante_egreso dc
        JOIN ct_comprobante_egreso c
          ON dc.id_comprobante = c.id
        JOIN ct_caja_banco ccb
          ON ccb.id = c.id_caja_banco
        JOIN ct_compras co
          ON dc.id_compra = co.id
        JOIN proveedor p
          ON c.id_proveedor = p.id
        LEFT JOIN ct_asientos_detalle cad
          ON c.id_asiento_cabecera = cad.id_asiento_cabecera
          AND cad.descripcion LIKE '%PROVEE%'
        LEFT JOIN plan_cuentas pc
          ON cad.id_plan_cuenta = pc.id
        LEFT JOIN plan_cuentas_empresa pce
          ON pc.id = pce.plan
          AND pce.id_empresa = id_empresa
      WHERE c.estado != 0
      AND cad.debe > 0)
    UNION ALL
    (SELECT
        '' aux,
        2 orden,
        db.id_asiento,
        CONCAT(p.razonsocial, ' # ', db.concepto, ' Ref: ', dd.numero, ' #Debito: ', db.id, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
        CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
        CONCAT('BAN-ND ', db.secuencia, ' | Ref: ', db.id),
        pce.plan,
        pc.nombre,
        co.id AS idc1,
        'DEB-BAN' tipo,
        co.fecha,
        db.fecha AS fecha_documento,
        db.secuencia,
        p.id AS id_proveedor,
        p.razonsocial,
        0 subtotal_0,
        0 subtotal_12,
        0 descuento,
        0 subtotal,
        0 iva_total,
        dd.abono,
        db.id_empresa
      FROM ct_debito_bancario_detalle dd
        JOIN ct_debito_bancario db
          ON dd.id_debito = db.id
        JOIN ct_compras co
          ON dd.id_compra = co.id
        JOIN proveedor p
          ON db.id_acreedor = p.id
        JOIN ct_caja_banco ccb
          ON ccb.id = db.id_banco
        LEFT JOIN ct_asientos_detalle cad
          ON co.id_asiento_cabecera = cad.id_asiento_cabecera
          AND cad.descripcion LIKE '%PROVEE%'
        LEFT JOIN plan_cuentas pc
          ON cad.id_plan_cuenta = pc.id
        LEFT JOIN plan_cuentas_empresa pce
          ON pc.id = pce.plan
          AND pce.id_empresa = id_empresa
      WHERE db.estado != 0)
    UNION ALL
    (SELECT
        '' aux,
        3 orden,
        cc.id_asiento_cabecera,
        CONCAT(p.razonsocial, ' # ', cc.detalle, ' Ref: ', co.secuencia_f, ' #Cruce_Cuentas: ', cc.id) AS detalle,

        CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
        CONCAT('CRUCE-CUENTAS ', cc.secuencia, ' | Ref: ', cc.id),

        pce.plan,
        pc.nombre,
        co.id AS idc2,
        'CRUC-CUENTA' tipo,
        co.fecha,
        cc.fecha AS fecha_documento,
        cc.secuencia,
        p.id AS id_proveedor,
        p.razonsocial,
        0 subtotal_0,
        0 subtotal_12,
        0 descuento,
        0 subtotal,
        0 iva_total,
        cc.total,
        cc.id_empresa
      FROM ct_cruce_cuentas cc
        JOIN ct_compras co
          ON cc.id_factura = co.id
        JOIN proveedor p
          ON cc.id_proveedor = p.id
        LEFT JOIN ct_asientos_detalle cad
          ON co.id_asiento_cabecera = cad.id_asiento_cabecera
          AND cad.descripcion LIKE '%PROVEE%'
        LEFT JOIN plan_cuentas pc
          ON cad.id_plan_cuenta = pc.id
        LEFT JOIN plan_cuentas_empresa pce
          ON pc.id = pce.plan
          AND pce.id_empresa = id_empresa
      WHERE cc.estado != 0)
    UNION ALL
    (SELECT
        '' aux,
        4 orden,
        cv.id_asiento_cabecera,
        CONCAT(p.razonsocial, ' # ', cv.detalle, ' Ref: ', dc.secuencia_factura, ' #Cruce: ', dc.id_comprobante) AS detalle,
        CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
        CONCAT('ACR-CR-AF ', cv.secuencia, ' | Ref: ', cv.id),
        pce.plan,
        pc.nombre,
        co.id AS idc3,
        'CRUC-VALOR' tipo,
        co.fecha,
        cv.fecha_pago AS fecha_documento,
        cv.secuencia,
        p.id AS id_proveedor,
        p.razonsocial,
        0 subtotal_0,
        0 subtotal_12,
        0 descuento,
        0 subtotal,
        0 iva_total,
        dc.total,
        cv.id_empresa
      FROM ct_cruce_valores cv
        JOIN ct_detalle_cruce dc
          ON cv.id = dc.id_comprobante
        JOIN ct_compras co
          ON dc.id_factura = co.id
        JOIN proveedor p
          ON cv.id_proveedor = p.id
        LEFT JOIN ct_asientos_detalle cad
          ON co.id_asiento_cabecera = cad.id_asiento_cabecera
          AND cad.descripcion LIKE '%PROVEE%'
        LEFT JOIN plan_cuentas pc
          ON cad.id_plan_cuenta = pc.id
        LEFT JOIN plan_cuentas_empresa pce
          ON pc.id = pce.plan
          AND pce.id_empresa = id_empresa
      WHERE cv.estado != 0)
    UNION ALL
    (SELECT
        '' aux,
        5 orden,
        r.id_asiento_cabecera,
        CONCAT(p.razonsocial, ' # ', r.descripcion, ' Ref: ', co.secuencia_f, ' #Retencion: ', r.id) AS detalle,
        CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
        CONCAT('ACR-RE ', r.secuencia, ' | Ref: ', r.id),
        pce.plan,
        pc.nombre,
        co.id AS idc4,
        'RETEN' tipo,
        co.fecha,
        r.fecha AS fecha_documento,
        r.nro_comprobante,
        p.id AS id_proveedor,
        p.razonsocial,
        0 subtotal_0,
        0 subtotal_12,
        0 descuento,
        0 subtotal,
        0 iva_total,
        (r.valor_fuente + r.valor_iva) AS total,
        r.id_empresa
      FROM ct_retenciones r
        JOIN ct_compras co
          ON r.id_compra = co.id
        JOIN proveedor p
          ON r.id_proveedor = p.id
        LEFT JOIN ct_asientos_detalle cad
          ON co.id_asiento_cabecera = cad.id_asiento_cabecera
          AND cad.descripcion LIKE '%PROVEE%'
        LEFT JOIN plan_cuentas pc
          ON cad.id_plan_cuenta = pc.id
        LEFT JOIN plan_cuentas_empresa pce
          ON pc.id = pce.plan
          AND pce.id_empresa = id_empresa
      WHERE r.estado != 0)
    UNION ALL
    (SELECT
        '' aux,
        6 orden,
        cem.id_asiento_cabecera,
        CONCAT(p.razonsocial, ' # ', cem.descripcion, ' Ref: ', dcem.id_secuencia, ' #Egreso Masivo: ', dcem.id, ' -- Metodo de pago: ', ccb.nombre) AS detalle,
        CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
        CONCAT('ACR-M ', cem.secuencia, ' | Ref: ', cem.id),
        pce.plan,
        pc.nombre,
        co.id AS idc5,
        'EGR-MASI' tipo,
        co.fecha,
        cem.fecha_comprobante AS fecha_documento,
        cem.secuencia,
        p.id AS id_proveedor,
        p.razonsocial,
        0 subtotal_0,
        0 subtotal_12,
        0 descuento,
        0 subtotal,
        0 iva_total,
        dcem.abono,
        cem.id_empresa
      FROM ct_comprobante_egreso_masivo cem
        JOIN ct_detalle_comprobante_egreso_masivo dcem
          ON dcem.id_comprobante = cem.id
        JOIN ct_compras co
          ON dcem.id_compra = co.id
        JOIN proveedor p
          ON dcem.id_proveedor = p.id
        JOIN ct_caja_banco ccb
          ON ccb.id = cem.id_caja_banco
        LEFT JOIN ct_asientos_detalle cad
          ON co.id_asiento_cabecera = cad.id_asiento_cabecera
          AND cad.descripcion LIKE '%PROVEE%'
        LEFT JOIN plan_cuentas pc
          ON cad.id_plan_cuenta = pc.id
        LEFT JOIN plan_cuentas_empresa pce
          ON pc.id = pce.plan
          AND pce.id_empresa = id_empresa
      WHERE cem.estado != 0)
    UNION ALL
    (SELECT
        '' aux,
        7 orden,
        da.id_asiento_cabecera,
        CONCAT(p.razonsocial, ' # ', da.concepto, ' Ref: ', co.secuencia_f, ' #Debito: ', dda.id_debito_acreedores) AS detalle,
        CONCAT(cad.id_plan_cuenta, ' | ', cad.descripcion),
        CONCAT('ACR-DB ', co.secuencia_factura, ' | Ref: ', da.id),
        pce.plan,
        pc.nombre,
        co.id AS idc6,
        'DEBITO' tipo,
        co.fecha,
        da.fecha_factura AS fecha_documento,
        da.secuencia,
        p.id AS id_proveedor,
        p.razonsocial,
        0 subtotal_0,
        0 subtotal_12,
        0 descuento,
        0 subtotal,
        0 iva_total,
        dda.total,
        da.id_empresa
      FROM ct_debito_acreedores da
        JOIN ct_detalle_debito_acreedores dda
          ON da.id = dda.id_debito_acreedores
        JOIN ct_compras co
          ON dda.id_factura = co.id
        JOIN proveedor p
          ON da.id_proveedor = p.id
        LEFT JOIN ct_asientos_detalle cad
          ON co.id_asiento_cabecera = cad.id_asiento_cabecera
          AND cad.descripcion LIKE '%PROVEE%'
        LEFT JOIN plan_cuentas pc
          ON cad.id_plan_cuenta = pc.id
        LEFT JOIN plan_cuentas_empresa pce
          ON pc.id = pce.plan
          AND pce.id_empresa = id_empresa
      WHERE da.estado != 0)) AS dvp
  WHERE dvp.id_empresa = id_empresa
  AND (id_proveedor = ''
  OR dvp.id_proveedor = id_proveedor)
  AND dvp.fecha BETWEEN desde AND hasta
  ORDER BY dvp.idc, dvp.id_proveedor, orden;
END
$$

DELIMITER ;

--
-- Create table `plan`
--
CREATE TABLE plan (
  id varchar(255) NOT NULL,
  nombre varchar(255) NOT NULL,
  descripcion varchar(255) NOT NULL,
  estado tinyint(4) DEFAULT 2 COMMENT '0: inactivo; 1: grupo; 2: detalle',
  id_padre varchar(255) DEFAULT NULL,
  id_usuariomod varchar(13) DEFAULT NULL,
  id_usuariocrea varchar(13) DEFAULT NULL,
  ip_creacion varchar(40) DEFAULT NULL,
  ip_modificacion varchar(40) DEFAULT NULL,
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 2048,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `FK_plan_cuentas_id_usuariocrea` on table `plan`
--
ALTER TABLE plan
ADD INDEX FK_plan_cuentas_id_usuariocrea (id_usuariocrea);

--
-- Create index `FK_plan_cuentas_id_usuariomod` on table `plan`
--
ALTER TABLE plan
ADD INDEX FK_plan_cuentas_id_usuariomod (id_usuariomod);

--
-- Create foreign key
--
ALTER TABLE plan
ADD CONSTRAINT FK_plan_cuentas_id_padre2 FOREIGN KEY (id_padre)
REFERENCES plan (id) ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_new_balance`
--
CREATE
PROCEDURE sp_new_balance (IN id_empresa varchar(255), IN desde varchar(255), IN hasta varchar(255), IN hasta_ varchar(255), IN anio varchar(255), IN ip varchar(255), IN id_usuario varchar(255))
BEGIN
  TRUNCATE TABLE new_db_balance;
  INSERT INTO new_db_balance (id_padre, id_plan, id_empresa, anio, plan, nombre, debe, haber, saldo, ip_creacion, ip_modificacion, id_usuariocrea, id_usuariomod)
    (SELECT
        p.id_padre,
        p.id,
        id_empresa AS id_empresa,
        anio AS anio,
        pe.plan,
        p.nombre,
        COALESCE(SUM(CASE WHEN SUBSTRING(pe.plan, 1, 1) = '2' THEN ad.debe * -1 ELSE ad.debe END), 0) AS debe,
        COALESCE(SUM(CASE WHEN SUBSTRING(pe.plan, 1, 1) = '2' THEN ad.haber * -1 ELSE ad.haber END), 0) AS haber,
        COALESCE(SUM(CASE WHEN SUBSTRING(pe.plan, 1, 1) = '2' THEN ad.debe * -1 ELSE ad.debe END), 0) - COALESCE(SUM(CASE WHEN SUBSTRING(pe.plan, 1, 1) = '2' THEN ad.haber * -1 ELSE ad.haber END), 0) AS saldo,
        ip AS ip,
        ip AS ip,
        id_usuario AS id_usuario,
        id_usuario AS id_usuario
      FROM plan_cuentas p
        LEFT JOIN plan_cuentas_empresa pe
          ON p.id = pe.id_plan
        LEFT JOIN ct_asientos_detalle ad
          ON p.id = ad.id_plan_cuenta
        LEFT JOIN ct_asientos_cabecera ac
          ON ad.id_asiento_cabecera = ac.id
      WHERE pe.id_empresa = id_empresa
      AND ac.id_empresa = id_empresa
      AND SUBSTRING(pe.plan, 1, 1) IN ('1', '2', '3')
      AND ac.fecha_asiento < hasta
      AND pe.plan IS NOT NULL
      GROUP BY pe.plan
      ORDER BY pe.plan, ac.fecha_asiento)
    UNION ALL
    (SELECT
        p.id_padre,
        p.id,
        id_empresa AS id_empresa,
        anio AS anio,
        pe.plan,
        p.nombre,
        COALESCE(SUM(ad.debe), 0) AS debe,
        COALESCE(SUM(ad.haber), 0) AS haber,
        COALESCE(SUM(ad.debe), 0) - COALESCE(SUM(ad.haber), 0) AS saldo,
        ip AS ip,
        ip AS ip,
        id_usuario AS id_usuario,
        id_usuario AS id_usuario
      FROM plan_cuentas p
        LEFT JOIN plan_cuentas_empresa pe
          ON p.id = pe.id_plan
        LEFT JOIN ct_asientos_detalle ad
          ON p.id = ad.id_plan_cuenta
        LEFT JOIN ct_asientos_cabecera ac
          ON ad.id_asiento_cabecera = ac.id
      WHERE pe.id_empresa = id_empresa
      AND ac.id_empresa = id_empresa
      AND SUBSTRING(pe.plan, 1, 1) IN ('4', '5')
      AND `ac`.`fecha_asiento` BETWEEN desde AND hasta_
      AND pe.plan IS NOT NULL
      GROUP BY pe.plan
      ORDER BY pe.plan, ac.fecha_asiento);

END
$$

DELIMITER ;

--
-- Create table `ct_detalle_cruce_cuentas_clientes`
--
CREATE TABLE ct_detalle_cruce_cuentas_clientes (
  id int(11) NOT NULL AUTO_INCREMENT,
  codigo varchar(255) DEFAULT NULL,
  id_comprobante int(11) NOT NULL,
  tipo varchar(13) DEFAULT NULL,
  id_anticipo int(11) DEFAULT NULL,
  secuencia_factura varchar(255) DEFAULT NULL,
  id_factura int(11) NOT NULL,
  fecha date NOT NULL,
  estado tinyint(4) NOT NULL,
  total_factura decimal(18, 2) NOT NULL,
  total decimal(18, 2) NOT NULL,
  observaciones text DEFAULT NULL,
  id_usuariocrea varchar(255) DEFAULT NULL,
  id_usuariomod varchar(255) DEFAULT NULL,
  ip_creacion varchar(255) DEFAULT NULL,
  ip_modificacion varchar(255) DEFAULT NULL,
  created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP(),
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 1365,
CHARACTER SET utf8mb3,
COLLATE utf8mb3_general_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `sp_clientes_deudas_pagos`
--
CREATE
PROCEDURE sp_clientes_deudas_pagos (IN id_empresa varchar(13), IN desde varchar(255), IN hasta varchar(255), IN cliente varchar(255))
BEGIN

  DECLARE sqlcliente varchar(255);


  /*and c.identificacion = cliente*/

  SELECT
    *,
    CASE WHEN dvp.tipo IN ('FAC', 'ND') THEN dvp.total_final ELSE 0 END AS deuda,
    CASE WHEN dvp.tipo NOT IN ('FAC', 'ND') THEN dvp.total_final ELSE 0 END AS abono,
    SUM(CASE WHEN dvp.tipo IN ('FAC', 'ND') THEN dvp.total_final ELSE -dvp.total_final END) OVER (PARTITION BY dvp.id_empresa ORDER BY dvp.id, dvp.identificacion, orden) AS saldo,
    SUM(CASE WHEN dvp.tipo IN ('FAC', 'ND') THEN dvp.total_final ELSE 0 END) OVER (PARTITION BY dvp.id_empresa ORDER BY dvp.id, dvp.identificacion, orden) AS total_deuda,
    SUM(CASE WHEN dvp.tipo NOT IN ('FAC', 'ND') THEN dvp.total_final ELSE 0 END) OVER (PARTITION BY dvp.id_empresa ORDER BY dvp.id, dvp.identificacion, orden) AS total_abonos
  FROM ((SELECT
        0 AS orden,
        CONCAT('FACT #', v.nro_comprobante, ' | Ref: ', v.id) AS detalle,
        IFNULL(v.concepto, 'No existe concepto') AS concepto,
        'FAC' AS tipo,
        v.id,
        v.fecha,
        v.fecha AS fecha_documento,
        v.nro_comprobante,
        c.identificacion,
        c.nombre,
        v.id_asiento,
        CONCAT(pe.plan, '|', p.nombre) AS detalle_cuenta,
        v.subtotal_0,
        v.subtotal_12,
        v.descuento,
        v.iva_total,
        v.total_final,
        v.id_empresa
      FROM ct_clientes AS c
        JOIN ct_ventas AS v
          ON c.identificacion = v.id_cliente
        JOIN ct_asientos_detalle ad
          ON v.id_asiento = ad.id_asiento_cabecera
        JOIN plan_cuentas_empresa pe
          ON ad.id_plan_cuenta = pe.id_plan
          AND pe.id_empresa = id_empresa
          AND pe.nombre LIKE '%CUENTA%'
          AND pe.plan LIKE '1.%'
        JOIN plan_cuentas p
          ON ad.id_plan_cuenta = p.id

          AND v.estado != 0)
    UNION ALL
    (SELECT
        1 AS orden,
        CONCAT('RET #', r.nro_comprobante, ' | Ref: ', r.id) AS detalle,
        IFNULL(r.descripcion, 'No existe concepto') AS concepto,
        'RET' AS tipo,
        v.id,
        v.fecha,
        r.fecha AS fecha_documneto,
        r.nro_comprobante,
        c.identificacion,
        c.nombre,
        r.id_asiento_cabecera,
        CONCAT(pe.plan, '|', p.nombre) AS detalle_cuenta,
        0 AS subtotal_0,
        0 AS subtotal_12,
        0 AS descuento,
        0 AS iva_total,
        (r.valor_fuente + r.valor_iva) AS total_final,
        r.id_empresa
      FROM ct_cliente_retencion AS r
        JOIN ct_ventas AS v
          ON r.id_factura = v.id
        JOIN ct_clientes AS c
          ON r.id_cliente = c.identificacion
        JOIN ct_asientos_detalle ad
          ON r.id_asiento_cabecera = ad.id_asiento_cabecera
        JOIN plan_cuentas_empresa pe
          ON ad.id_plan_cuenta = pe.id_plan
          AND pe.id_empresa = id_empresa
          AND pe.nombre NOT LIKE 'CUENTAS%'
        LEFT JOIN plan_cuentas p
          ON ad.id_plan_cuenta = p.id
      WHERE r.estado != 0
      GROUP BY v.id)
    UNION ALL
    (SELECT
        2 AS orden,
        CONCAT('COM-IN #', ci.secuencia, ' | Ref: ', ci.id) AS detalle,
        IFNULL(ci.observaciones, 'No existe concepto') AS concepto,
        'COMP-ING' AS tipo,
        v.id,
        v.fecha,
        ci.fecha AS fecha_documento,
        ci.secuencia,
        c.identificacion,
        c.nombre,
        ci.id_asiento_cabecera,
        CONCAT(pe.plan, '|', p.nombre) AS detalle_cuenta,
        0 AS subtotal_0,
        0 AS subtotal_12,
        0 AS descuento,
        0 AS iva_total,
        dci.total,
        ci.id_empresa
      FROM ct_detalle_comprobante_ingreso AS dci
        JOIN ct_comprobante_ingreso AS ci
          ON dci.id_comprobante = ci.id
        JOIN ct_ventas AS v
          ON dci.id_factura = v.id
        JOIN ct_clientes AS c
          ON ci.id_cliente = c.identificacion
        JOIN ct_asientos_detalle AS ad
          ON ci.id_asiento_cabecera = ad.id_asiento_cabecera
        JOIN plan_cuentas_empresa pe
          ON ad.id_plan_cuenta = pe.id_plan
          AND pe.id_empresa = id_empresa
          AND pe.nombre LIKE '%CAJA%'
        LEFT JOIN plan_cuentas p
          ON ad.id_plan_cuenta = p.id
      WHERE ci.estado != 0)
    UNION ALL
    (SELECT
        3 AS orden,
        CONCAT('CR-V #', cv.secuencia, ' | Ref: ', cv.id) AS detalle,
        IFNULL(cv.observacion, 'No existe concepto') AS concepto,
        'CRUCE-VAL' AS tipo,
        v.id,
        v.fecha,
        cv.fecha_pago AS fecha_documento,
        cv.secuencia,
        c.identificacion,
        c.nombre,
        cv.id_asiento_cabecera,
        CONCAT(pe.plan, '|', p.nombre) AS detalle_cuenta,
        0 AS subtotal_0,
        0 AS subtotal_12,
        0 AS descuento,
        0 AS iva_total,
        dc.total,
        cv.id_empresa
      FROM ct_detalle_cruce_clientes dc
        JOIN ct_cruce_valores_cliente cv
          ON dc.id_comprobante = cv.id
        JOIN ct_ventas AS v
          ON dc.id_factura = v.id
        JOIN ct_clientes AS c
          ON cv.id_cliente = c.identificacion
        JOIN ct_asientos_detalle ad
          ON cv.id_asiento_cabecera = ad.id_asiento_cabecera
        JOIN plan_cuentas_empresa pe
          ON ad.id_plan_cuenta = pe.id_plan
          AND pe.id_empresa = id_empresa
          AND pe.nombre LIKE '%CUENTAS%'
        LEFT JOIN plan_cuentas p
          ON ad.id_plan_cuenta = p.id
      WHERE cv.estado != 0)
    UNION ALL
    (SELECT
        4 AS orden,
        CONCAT('CR-C #', ccc.secuencia, ' | Ref: ', ccc.id) AS detalle,
        IFNULL(ccc.detalle, 'No existe concepto') AS concepto,
        'CRUCE-CUE' AS tipo,
        v.id,
        v.fecha,
        ccc.fecha AS fecha_documento,
        ccc.secuencia,
        c.identificacion,
        c.nombre,
        ccc.id_asiento_cabecera,
        CONCAT(pe.plan, '|', p.nombre) AS detalle_cuenta,
        0 AS subtotal_0,
        0 AS subtotal_12,
        0 AS descuento,
        0 AS iva_total,
        ccc.total,
        ccc.id_empresa
      FROM ct_detalle_cruce_cuentas_clientes dcc
        JOIN ct_cruce_cuentas_clientes ccc
          ON dcc.id_comprobante = ccc.id
        JOIN ct_ventas v
          ON ccc.id_factura = v.id
        JOIN ct_clientes AS c
          ON ccc.id_cliente = c.identificacion
        JOIN ct_asientos_detalle ad
          ON ccc.id_asiento_cabecera = ad.id_asiento_cabecera
        JOIN plan_cuentas_empresa pe
          ON ad.id_plan_cuenta = pe.id_plan
          AND pe.id_empresa = id_empresa
          AND pe.nombre LIKE '%CUENTAS%'
          AND pe.plan LIKE '1.%'
        LEFT JOIN plan_cuentas p
          ON ad.id_plan_cuenta = p.id
      WHERE ccc.estado != 0)
    UNION ALL
    (SELECT
        5 orden,
        CONCAT('NC #', nc.nro_comprobante, ' | Ref: ', nc.id) detalle,
        IFNULL(nc.observacion, 'No existe concepto') AS concepto,
        'NC' AS tipo,
        IFNULL(v.id, nc.id_factura),
        IFNULL(v.fecha, vn.fecha),
        nc.fecha AS fecha_documento,
        nc.nro_comprobante,
        c.identificacion,
        c.nombre,
        nc.id_asiento_cabecera,
        CONCAT(pe.plan, '|', p.nombre) AS detalle_cuenta,
        0 AS subtotal_0,
        0 AS subtotal_12,
        0 AS descuento,
        0 AS iva_total,
        nc.total_credito,
        nc.id_empresa
      FROM ct_nota_credito_clientes nc
        LEFT JOIN ct_devolucion_productos dp
          ON nc.id = dp.id_nota_credito
        LEFT JOIN ct_detalle_credito_clientes dnc
          ON nc.id = dnc.id_not_cred
        LEFT JOIN ct_ventas v
          ON dnc.id_factura = v.id
        LEFT JOIN ct_ventas vn
          ON nc.id_factura = vn.id
        JOIN ct_clientes c
          ON nc.id_cliente = c.identificacion
        LEFT JOIN ct_asientos_detalle ad
          ON nc.id_asiento_cabecera = ad.id_asiento_cabecera
          AND ad.descripcion LIKE '%CUENTAS%'
        LEFT JOIN plan_cuentas_empresa pe
          ON ad.id_plan_cuenta = pe.id_plan
          AND pe.id_empresa = nc.id_empresa
        LEFT JOIN plan_cuentas p
          ON ad.id_plan_cuenta = p.id
      WHERE nc.estado != 0
      GROUP BY nc.id)
    UNION ALL
    (SELECT
        6 AS orden,
        CONCAT('ND #', v.nro_comprobante, ' | Ref: ', v.id) AS detalle,
        IFNULL(v.concepto, 'No existe concepto') AS concepto,
        'ND' AS tipo,
        v.id,
        v.fecha,
        v.fecha AS fecha_documento,
        v.nro_comprobante,
        c.identificacion,
        c.nombre,
        v.id_asiento,
        CONCAT(pe.plan, '|', p.nombre) AS detalle_cuenta,
        v.subtotal_0,
        v.subtotal_12,
        v.descuento,
        v.iva_total,
        v.total_final,
        v.id_empresa
      FROM ct_clientes AS c
        JOIN ct_ventas AS v
          ON c.identificacion = v.id_cliente
        JOIN ct_asientos_detalle ad
          ON v.id_asiento = ad.id_asiento_cabecera
        JOIN plan_cuentas_empresa pe
          ON ad.id_plan_cuenta = pe.id_plan
          AND pe.id_empresa = id_empresa
          AND pe.nombre LIKE '%CUENTAS POR COBRAR%'
        LEFT JOIN plan_cuentas p
          ON ad.id_plan_cuenta = p.id
      WHERE v.estado != 0
      AND v.tipo = 'N-D')) AS dvp
  WHERE dvp.id_empresa = id_empresa
  AND dvp.fecha BETWEEN desde AND hasta
  AND (cliente = ''
  OR dvp.identificacion = cliente)
  -- fecha de la venta v.fecha
  -- cliente id_cliente
  ORDER BY dvp.id, orden, dvp.identificacion;



END
$$

DELIMITER ;

